SELECT 'moj-all-verified-judgments-review-002-chunk-125' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"98a37874-b46f-5719-b491-953b5171516b","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة بعض محتويات من منزل - سرقة ذهب -رجوع عن اقرار مصدق شرع ا -تعاطي احلشيش - دعوى املدعي اخلاص واملطالبة بقيمة الذهب -احلكم بإعادة قيمة املسروقات -التعزير بالسجن واجللد .","document_number":"3457976","case_number":"3376429","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران وبن املعاملة الواردة إلينا من فرع هيئة التحقيق واالدعاء العام مبنطقة جنران ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/08","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة بعض محتويات من منزل - سرقة ذهب -رجوع عن اقرار مصدق شرع ا -تعاطي احلشيش - دعوى املدعي اخلاص واملطالبة بقيمة الذهب -احلكم بإعادة قيمة املسروقات -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3457976 :‬تاريخه ‪1434/03/08 :‬هـ‬\n                           ‫رقم الدعوى ‪3376429 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34245449‬تاريخه ‪1434/06/19 :‬هـ‬\n\n\n\n      ‫ســرقة‪ -‬انتهــاك حرمــة منــزل ‪ -‬ســرقة بعــض محتويــات مــن منــزل ‪-‬‬\n      ‫ســرقة ذهــب ‪ -‬رجــوع عــن اقــرار مصــدق شــرع ًا ‪ -‬تعاطــي احلشــيش ‪-‬‬\n      ‫دعــوى املدعــي اخلــاص واملطالبــة بقيمــة الذهــب ‪ -‬احلكــم بإعــادة قيمــة‬\n                                      ‫املســروقات ‪-‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪-1‬عــن عــروة عــن عائشــة رضــي اهلل عنهــا أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم قــال «( ادرؤوا احلــدود عــن املســلمني مــا اســتطعتم فــإن وجــدمت‬\n      ‫للمســلم مخرج ـ ًا فخلــوا ســبيله فــإن اإلمــام ألن يخطــئ يف العفــو‬\n      ‫خيــر لــه مــن أن يخطــئ يف العقوبــة)» ‪ .‬أخرجــه الترمــذي يف اجلامــع‬\n      ‫(‪ )318/2‬والبيهقــي يف الســن الكبــرى (‪ )238/8‬والــدار قطنــي يف الســن‬\n                                        ‫(‪ )324/2‬واحلاكــم يف املســتدرك (‪.)384/4‬‬\n      ‫‪-2‬قــال البهوتــي رحمــه اهلل ‪ ( :‬وال يقبــل رجــوع املقــر عــن إقــراره إال‬\n      ‫فيمــا كان حــد ًا فأمــا حقــوق اآلدميــن وحقــوق اهلل تعالــى التــي ال‬\n      ‫تــدرأ بالشــبهات كالــزكاة ‪ ،‬والكفــارات ‪ ،‬فــا يقبــل رجوعــه عنهــا ) ‪.‬‬\n                                                         ‫كشــاف القنــاع (‪.)408/15‬‬\n      ‫‪-3‬قــال البهوتــي رحمــه اهلل ‪ ( :‬ومــن أتلــف ولــو خط ـ ًأ أو ســهو ًا مــا ًال‬\n             ‫محترم ـ ًا لغيــره بغيــر إذنــه َضمِ َنــه )‪ .‬كشــاف القنــاع (‪.)302/9‬‬\n                                         ‫‪-4‬املادة (‪ )3‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n‫‪111‬‬\n\f‫توجيــه االتهــام للمدعــى عليــه بشــراء ربــع كيلــو مــن احلشــيش املخــدر‬\n‫بقصــد التعاطــي‪ ،‬وســرقته ذهب ـ ًا مــن منــزل أحــد املواطنــن‪ ،‬حيــث‬\n‫تقــدم أحــد املواطنــن بشــكوى لــدى مخفــر الشــرطة عــن تعــرض منزلــه‬\n‫للســرقة‪ ،‬وعنــد الوصــول إلــى املوقــع الحــظ أفــراد الدوريــة أن الســارق‬\n‫قطــع أحــد نوافــذ غرفــة النــوم‪ ،‬وقــد ســرق الذهــب مــن دوالب غرفــة‬\n‫النــوم‪ ،‬وبعــد أســبوعني تقريب ـ ًا مت القبــض علــى املدعــى عليــه مــن قبــل‬\n‫التحريــات والبحــث اجلنائــي مبحافظــة اخلبــر علمـ ًا بــأن الســرقة مبدينــة‬\n‫جنــران‪ ،‬وقــد عثربحــوزة املدعــى عليــه علــى مبلــغ مالــي وجهــاز جــوال‬\n‫وحافظــة نقــود شــخصية‪ ،‬لــذا طلــب املدعــي العــام إقامــة حــد الســرقة‪،‬‬\n‫كمــا حضــر املدعــي اخلــاص وطالــب بقيمــة الذهــب‪ ،‬وأنكــر املدعــى‬\n‫عليــه مــا نســب إليــه‪ ،‬كمــا ذكــر املدعــى عليــه أنــه وجــد الذهــب أمــام‬\n‫بــاب منــزل املدعــي اخلــاص‪ ،‬وجــود إقــرار مصــدق شــرع ًا للمدعــى عليــه‬\n‫بصحــة مانســب إليــه‪ ،‬لكــن رجــع املدعــى عليــه عــن إقــراره‪ ،‬وبعــد‬\n‫املداولــة صــدر احلكــم علــى املدعــى عليــه بإرجــاع قيمــة الذهــب للمدعي‬\n‫اخلــاص‪ ،‬وصــرف النظــر عــن إقامــة حــد الســرقة ‪ ،‬وتعزيــر املدعــى عليــه‬\n          ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫بالســجن واجللــد ‪ُ ،‬‬\n\n\n\n\n                                                                                   ‫‪112‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n      ‫ـاء علــى‬\n            ‫لدينــا نحــن …و…و…القضــاة باحملكمــة العامــة بنجــران وبنـ ً‬\n      ‫املعاملــة الــواردة إلينــا مــن فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة‬\n      ‫جنــران برقــم ه ـ ن ‪ 1286/4/6/1‬وتاريــخ ‪1433/01/26‬ه ـ واملقيــدة‬\n      ‫باحملكمــة برقــم ‪33199576‬يف ‪1433/01/30‬ه ـ واحملالــة للمكتــب‬\n      ‫القضائــي ‪ .............‬برقــم ‪ 3376429‬يف ‪1433/01/30‬ه ـ ويف يــوم‬\n      ‫الثالثــاء املوافــق ‪1433/ 7/22‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫العاشــرة والنصــف وفيهــا حضــر املدعــي العــام …مبوجــب خطــاب‬\n      ‫التكليــف رقــم ه ـ ن ‪ 13137/2/1‬وادعــى علــى احلاضــر معه…ســعودي‬\n      ‫ا يف دعــواه إنــه بتاريــخ‬\n                                ‫اجلنســية مبوجــب الســجل املدنــي رقــم ( …) قائـ ً‬\n      ‫‪1432/10/21-20‬ه ـ تقدم…ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n      ‫رقــم (…) بشــكوى لــدى مخفــر شــرطة حــي ‪ ....‬عــن تعــرض منزلــه‬\n      ‫للســرقة إذ ســرق منــه ذهــب تقــدر قيمتــه ب ـ (‪ )40.000‬أربعــن ألــف ريــال‬\n      ‫وورد يف احملضــر املعــد مــن قبــل الدوريــات األمنيــة رقــم (‪ )46202‬أنــه‬\n      ‫يف متــام الســاعة (‪ )1:59‬صباحـ ًا مــن يــوم االثنــن ‪1432/10/21-20‬ه ـ‬\n      ‫تلقــوا بالغـ ًا مــن قبــل العمليــات عــن وجــود شــكوى بســرقة منــزل وعنــد‬\n      ‫الوصــول إلــى املوقــع الحظــوا أن الســارق قطــع أحــد النوافــذ التابعــة‬\n      ‫لغرفــة النــوم وباالنتقــال إلــى املنــزل بحــي ‪ .....‬مت تصويــر املوقــع وتبــن‬\n      ‫أن املنــزل مســتأجر ومكــون مــن دور أرضــي قــدمي وقــد ســرق الذهــب‬\n      ‫مــن دوالب غرفــة النــوم إذ كان يف شــنطة صغيــرة مــن الفئــة الوســطى‬\n      ‫وقــد مت الدخــول إلــى غرفــة النــوم عــن طريــق قطــع شــبك النافــذة وقــد‬\n\n‫‪113‬‬\n\f‫مت مخاطبــة رئيــس مخفــر شــرطة حــي ‪ .......‬بخطابنــا رقــم (‪)1157‬‬\n‫وتاريــخ ‪1433/1/23‬ه ـ حلجــز تعليقــة الذهــب التــي باعهــا املتهــم علــى‬\n‫…متهيــد ًا للتصــرف فيهــا مبــا تأمــر بــه احملكمــة املختصــة عنــد طلــب‬\n‫ذوي الشــأن وقــد مت القبــض علــى املتهــم بتاريــخ ‪1432/11/5‬ه ـ مــن‬\n‫قبــل التحريــات والبحــث اجلنائــي بشــرطة محافظــة اخلبــر ووجــد بحوزتــه‬\n‫مبلــغ مالــي قــدره (‪ )9916‬تســعة آالف وتســع مئــة وســتة عشــر ريــا ًال‬\n‫وجهــاز جــوال ومحفظتــه الشــخصية (بطاقــة أحــوال‪ ،‬بطاقــة شــخصية‪،‬‬\n‫شــريحة جــوال) ثــم مت تســليمه إلــى شــعبة الســجن العــام بنجــران‬\n‫بخطــاب مديــر إدارة ســجون املنطقــة الشــرقية رقــم (‪)6/21/3255/9‬‬\n‫وتاريــخ ‪1432/11/24‬ه ـ وبســماع أقــوال املشــتكي …أفــاد أنــه يف‬\n‫عصــر يــوم األحــد ‪1432/10/20‬ه ـ خــرج مــن منزلــه هــو وأهلــه وعنــد‬\n‫الســاعة الواحــدة صباح ـ ًا عــاد إلــى املنــزل ووجــد غرفــة النــوم مفتوحــة‬\n‫والنافــذة مكســورة ودوالب الثيــاب مفتــوح وشــنطة الذهــب موضوعــة‬\n‫علــى الســرير وكان بهــا عــدد (‪ )2‬تعليقــة و (‪ )5‬خــوامت و (‪ )2‬ســواره‬\n‫وسلســال يــدوي وقــد ســرقت‪،‬فاتصل بالدوريــات األمنيــة وبســماع‬\n‫أقــوال …ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (…) أفــاد‬\n‫بأنــه يف مســاء يــوم األربعــاء ‪1432/10/30‬ه ـ حضــر إليــه املتهــم يف‬\n‫احملــل الــذي يعمــل بــه (شــركة ‪ ...‬لبيــع املصوغــات الذهبيــة) وبــاع عليــه‬\n‫تعليقــة ذهــب بقيمــة (‪ )9300‬تســعة آالف وثــاث مئــة ريــال وباســتجواب‬\n‫املتهــم أقــر بأنــه بتاريــخ ‪1432/10/20‬ه ـ وبعــد صــاة العشــاء تقريب ـ ًا‬\n‫قــام باالجتــاه مبفــرده إلــى منــزل …الكائــن بحــي ‪ .......‬بقصــد الســرقة‬\n‫واســتعمل يف ذلــك منشــار يــدوي وجــده بجانــب مضخــة امليــاه باملنــزل‬\n‫واجتــه إلــى النافــذة املطلــة علــى غرفــة النــوم وقــام بقطــع بعــض حواجــز‬\n\n\n                                                                                    ‫‪114‬‬\n\f      ‫حمايــة النافــذة حيــث أنــه علــى علــم مبداخــل ومخــارج ذلــك البيــت‬\n      ‫بحكــم أنــه تعــود ملكيتــه لوالــده ومؤجــر علــى …‪ ،‬ودخــل مــن خــال‬\n      ‫النافــذة إلــى داخــل غرفــة النــوم وقــام بفتــح الــدوالب وعثــر علــى شــنطة‬\n      ‫ففتحهــا ووجــد بداخلهــا مجوهــرات فقــام بحمــل املجوهــرات يف جيبــه‬\n      ‫وتــرك الشــنطة بداخــل الغرفــة وخــرج مــن النافــذة حيــث كان يضــع‬\n      ‫الذهــب يف جيبــه وبعــد يومــن تقريبـ ًا قــام باالجتــاه إلــى إحــدى محــات‬\n      ‫الذهــب فبــاع قطعــة منــه علــى محــل ‪ ...‬مببلــغ وقــدره (‪ )9300‬تســعة‬\n      ‫آالف وثــاث مئــة ريــال ثــم اجتــه إلــى محافظــة خميــس مشــيط وبــاع‬\n      ‫علــى إحــدى محــات الذهــب هنــاك قطعــة أخــرى مببلــغ (‪)10700‬‬\n      ‫عشــرة آالف وســبعمائة ريــال ثــم اجتــه إلــى املنطقــة الشــرقية وهنــاك‬\n      ‫مت القبــض عليــه وكان بحوزتــه مبلــغ (‪ )9916‬تســعة آالف وتســع مئــة‬\n      ‫وســتة عشــر ريــا ًال بقيــة مــا باعــه مــن الذهب‪،‬وصــدق إقــراره بذلــك‬\n      ‫شــرعاً‪ ،‬كمــا أقــر بأنــه اشــترى (‪ )0.25‬ربــع كيلــو جــرام تقريبــا مــن‬\n      ‫ا وقــد انتهــى التحقيــق إلــى توجيــه‬     ‫احلشــيش املخــدر‪ ،‬وتعاطــاه كام ـ ً‬\n      ‫االتهــام لــ…… بشــراء (‪ )0.25‬ربــع كيلــو مــن احلشــيش املخــدر بقصــد‬\n      ‫ا مجرمـ ًا اســتناد ًا للفقــرة الثانيــة مــن‬\n                                                   ‫التعاطــي وتعاطيــه لــه ممــا يعــد فعـ ً‬\n      ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/9‬ه ـ وســرقته‬\n      ‫ذهبـ ًا مــن منــزل …وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬ما جــاء يف إقراره‬\n      ‫املصــدق شــرع ًا املنــوه عنــه واملــدون علــى ص (‪ )16.15‬وكذلــك مــا جــاء‬\n      ‫يف أقوالــه املنــوه عنهــا املدونــة علــى ص (‪)14-11‬مــن الدفتــر رقــم (‪)4‬‬\n       ‫املرفــق لفــة (‪ )60‬وص(‪ )4-2‬مــن الدفتــر رقــم ( ‪ )5‬املرفــق لفــة(‪)85‬‬\n      ‫‪ -2‬مــا جــاء يف أقــوال «‪ ».......‬املنــوه عنهــا واملدونــة علــى ص (‪ )15-12‬مــن‬\n\n\n‫‪115‬‬\n\f                                                           ‫الدفتــر املرفــق لفة (‪)10‬‬\n‫‪ -3‬مــا جــاء يف احملضــر املعــد مــن قبــل دوريــات األمــن املنــوه عنــه املرفــق‬\n                                                                               ‫لفــة (‪)2‬‬\n‫‪ -4‬مــا جــاء يف محضــر االنتقــال واملعاينــة املنــوه عنــه املــدون علــى ص (‪)5‬‬\n                                                        ‫مــن الدفتــر املرفــق لفــة (‪)1‬‬\n‫‪ -5‬مــا جــاء يف تقريــر فنــي التصويــر رقــم (‪ )3‬املنــوه عنــه املرفــق لفــة‬\n‫(‪ )87‬وحيــث إن مــا أقــدم عليــه …وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫مــن ســرقته مــا ًال محترمـ ًا بالــغ النصــاب ال شــبهة لــه فيــه مــن حــرزه بعــد‬\n‫هتكــه وشــراءه كميــة مــن احلشــيش املخــدر وتعاطيــه لــه فعــل محــرم‬\n‫شــرع ًا ومعاقــب عليــه نظام ـ ًا لــذا اطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n                                                            ‫واحلكــم عليــه باآلتــي‪:‬‬\n       ‫‪ -1‬حد السرقة الوارد يف اآلية الكرمية رقم (‪ )38‬من سورة املائدة‬\n‫‪ -2‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n                                            ‫مكافحــة املخــدرات املنــوه عنــه‬\n‫‪ -3‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ عقوبــة الســجن اســتناد ًا‬\n‫للفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املنــوه‬\n‫عنــه (علم ـ ًا بــأن احلــق اخلــاص ال زال قائم ـاً) وبــاهلل التوفيــق هكــذا‬\n‫ادعــى كمــا حضــر يف هــذه اجللســة املدعــي باحلــق اخلــاص … ســعودي‬\n    ‫اجلنســية بالســجل املدنــي رقــم … ســجل جنــران يف ‪ 1427/8/12‬ه ـ‬\n‫ا يف دعــواه لقــد قــام املدعــى عليــه بكســر نافــذة منزلــي‬       ‫ثــم ادعــى قائـ ً‬\n‫والدخــول إلــى غرفــة النــوم وقــام بفتــح الــدوالب وفتــح الشــنطة التــي‬\n‫بداخلــه وســرق منهــا ذهــب عبــارة عــن (‪)2‬تعليقــه و(‪)5‬خوامت و(‪)2‬ســواره‬\n‫وسلســال يــدوي وال أعلــم كــم عيارهــا أو وزنهــا وتقــدر قيمتهــا بثالثــة‬\n\n\n                                                                                           ‫‪116‬‬\n\f      ‫وأربعــون ألــف وســبعمائة ريــال أطلــب إلزامــه بإعــادة التعليقــة التــي‬\n      ‫وجــدت لــدى محــل … مبنطقــة جنــران حيــث قــام املدعــى عليــه ببيعهــا‬\n      ‫لهــم كمــا أطلــب إلزامــه بدفــع قيمــة بقيــة املســروقات وقدرهــا أربعــة‬\n      ‫وثالثــون ألــف وأربعمائــة ريــال لــي حــا ًال هــذه دعــواي وبعــرض دعــوى‬\n      ‫ا‬\n      ‫املدعــي العــام واملدعــي باحلــق اخلــاص علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫الصحــة ملــا جــاء بدعــوى املدعــي العــام واملدعــي باحلــق اخلــاص مــن قيامي‬\n      ‫بســرقة ذهــب مــن منــزل املدعــي باحلــق اخلــاص والصحيــح أنــي وجــدت‬\n      ‫ذهب ـ ًا مرمي ـ ًا عنــد بــاب بيــت املدعــي باحلــق اخلــاص ولــم أعــد أتذكــر‬\n      ‫نوعيــة الذهــب الــذي وجدتــه وقــد بعتــه كلــه مببلــغ وقــدره عشــرون ألــف‬\n      ‫ريــال ولــم يبقــى منــه إال تعليقــة واحــدة كانــت يف الشــقق يف املنطقــة‬\n      ‫الشــرقية التــي مت مداهمتــي فيهــا وقــد تركتهــا يف الشــقة كمــا أنــه‬\n      ‫الصحــة ملــا جــاء بدعــوى املدعــي العــام مــن قيامــي بشــراء (‪ )0.25‬ربــع‬\n      ‫كيلــو مــن احلشــيش املخــدر بقصــد التعاطــي وأننــي تعاطيتــه هكــذا‬\n      ‫أجــاب وبطلــب البينــة مــن املدعــي العــام واملدعــي باحلــق اخلــاص أجــاب‬\n      ‫ا بينتــي مــا ذكــر يف الئحة الدعوى وما تضمنته‬          ‫كل واحــد منهمــا قائـ ً‬\n      ‫أوراق املعاملــة هكــذا قــررا فجــرى منــا االطــاع علــى أوراق املعاملــة‬\n      ‫ومنهــا إقــرار املدعــى عليــه املصــدق شــرع ًا مــن احملكمــة اجلزئيــة‬\n      ‫بنجــران املــدون علــى صفحــة رقــم (‪ )16،15‬مــن دفتــر تقريــر األحــوال‬\n      ‫األمنيــة املرفــق باملعاملــة علــى اللفــة رقــم(‪ )60‬ونصــه ( أقــر أنــا املدعــو ‪..‬‬\n      ‫ســعودي اجلنســية أحمــل بطاقــة رقــم ‪ ...‬أبلــغ مــن العمــر ‪ 30‬ســنة عاطــل‬\n      ‫عــن العمــل أنــه بتاريــخ ‪1432/10/20‬ه ـ وكان ذلــك بعــد صــاة العشــاء‬\n      ‫تقريب ـ ًا وقمــت باالجتــاه مبفــردي إلــى منــزل املدعــو ‪ ...‬الكائــن بحــي‬\n      ‫‪ ......................‬حيــث كنــت أضمــر ارتــكاب حالــة الســرقة وقــد‬\n\n\n‫‪117‬‬\n\f‫ا معــي منشــر وجدتــه مرمــي وواقــع علــى األرض‬      ‫أقدمــت علــى ذلــك حامـ ً‬\n‫بجانــب دينمــو امليــاه حيــث تناولتــه مــن األرض وقمــت باالجتــاه إلــى‬\n‫النافــذة املطلــة علــى غرفــة النــوم وقمــت بقــص قطعة من احلديــد املعروفة‬\n‫( بحامــي حرامــي ) وهــي غطــاء خارجــي مــن احلديــد حيــث أننــي علــى‬\n‫علــم مبداخــل ومخــارج ذلــك البيــت بحكــم أنــه يعــود لوالــدي ومؤجــر‬\n‫علــى املدعــو ‪ ....‬حيــث قبــل أن أقــدم علــى ذلــك أخــذت باملعاينــة خشــية‬\n‫مــن مالحظتــي مــن قبــل أي مــن املــارة وعندمــا لــم أالحــظ أحــد ًا بالقــرب‬\n‫مــن ذلــك البيــت قمــت بدخولــه مــن خــال النافــذة إلــى داخــل غرفــة النــوم‬\n‫وقــد دخلــت وقمــت بفتــح الــدوالب وعثــرت علــى شــنطة وقمــت بفتحهــا‬\n‫ووجــدت بداخلهــا مجوهــرات وقــد قمــت بحملهــا وتــرك الشــنطة بداخــل‬\n‫الغرفــة ومتكنــت مــن اخلــروج مــن خــال النافــذة مــرة أخــرى حيــث كنت‬\n‫أضــع الذهــب بداخــل جيوبــي يف الثــوب وبعــد ذلــك اجتهــت إلــى مســجد‬\n‫يف مستشــفى ‪ ......‬ومكثــت فيــه مــا يقــارب اليومــن وبعــد ذلــك اجتهــت‬\n‫إلــى إحــدى محــات الذهــب لبيــع قطعــة منــه وبعــت قطعــة علــى محــل ‪...‬‬\n‫مببلــغ وقــدره ‪ 9300‬ريــال ثــم اجتهــت مــع الكــداد إلــى خميــس مشــيط‬\n‫( أجــرة) ثــم قمــت ببيــع القطعــة الثانيــة يف محــات لبيــع الذهب ال أعرفه‬\n‫بخميــس مشــيط مببلــغ وقــدره ‪ 10700‬ريــال ثــم اجتهــت إلــى املنطقــة‬\n‫الشــرقية مبفــردي وهنــاك مت القبــض علــي عــن طريــق شــرطة الشــرقية‬\n‫اخلبــر حيــث قمــت بالتمويــه علــى رجال األمن عند أخــذ أقوالي واملراوغة‬\n‫يف قــول احلقيقــة وهــذه املــرة الثانيــة بارتــكاب مثــل هــذه الســرقة هــذا‬\n‫إقــراري بطوعــي واختيــاري وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا‬\n‫ال مجبــر وال مكــره وعليــه أذنــت ملــن يشــهد واهلل خيــر الشــاهدين وعليه‬\n‫ا‬ ‫أقــر وأوقــع املقــر مبــا فيــه …إبهامــه ) أ ‪ .‬ه ـ وبعرضــه عليــه أجــاب قائـ ً‬\n\n\n                                                                                        ‫‪118‬‬\n\f      ‫الصحــة ملــا جــاء بهــذا اإلقــرار حيــث أنــه أخــذ منــي بالقــوة واإلكــراه‬\n      ‫ا ال بينــة لــدي هكــذا‬   ‫وبســؤاله البينــة علــى دعــوى اإلكــراه أجــاب قائـ ً‬\n      ‫أجــاب كمــا جــرى منــا االطــاع علــى اســتجواب املدعــى عليــه حتقيقـ ًا‬\n      ‫املدونــة علــى ص (‪)14-11‬مــن الدفتــر رقــم (‪ )4‬املرفــق باملعاملــة علــى‬\n      ‫اللفــة رقــم (‪ )60‬وص(‪ )4-2‬مــن الدفتــر رقــم ( ‪ )5‬املرفــق باملعاملــة علــى‬\n      ‫اللفــة رقــم (‪ )85‬واملتضمــن أنــه اشــترى ببعــض مبلــغ الذهــب املســروق‬\n      ‫ا الصحــة ملــا‬ ‫ربــع كيلــو مــن احلشــيش كمــا وبعرضــه عليــه أجــاب قائـ ً‬\n      ‫جــاء بهــذا اإلقــرار حيــث أنــه أخــذ منــي بالقــوة واإلكــراه وبســؤاله البينة‬\n      ‫ا ال بينــة لــدي هكــذا أجــاب كمــا‬      ‫علــى دعــوى اإلكــراه أجــاب قائ ـ ً‬\n      ‫جــرى منــا االطــاع علــى أقــوال املدعــو …املدونــة علــى صفحــة‬\n      ‫(‪ )15،14،13،12‬مــن دفتــر تقريــر األحــوال األمنيــة املرفــق باملعاملــة‬\n      ‫علــى اللفــة رقــم (‪ )10‬فوجدناهــا مطابقــة ملــا ذكــره املدعــي العــام كمــا‬\n      ‫جــرى منــا االطــاع علــى مــا جــاء يف احملضــر املعــد مــن قبــل دوريــات‬\n      ‫األمــن املرفــق باملعاملــة علــى اللفــة رقــم (‪ )2‬ومحضــر االنتقــال واملعاينــة‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )5‬مــن دفتــر التحقيــق رقــم (‪ )1‬املرفــق لفــة‬\n      ‫رقــم (‪ )1‬كمــا جــرى االطــاع علــى تقريــر فنــي التصويــر رقــم (‪)3‬‬\n      ‫املرفقــة لفــة رقــم (‪ )87‬فوجدناهــا جميع ـ ًا مطابقــة ملــا جــاء يف دعــوى‬\n      ‫املدعــي العامكمــا جــرى منــا االطــاع علــى صــورة صحيفــة برنــت‬\n      ‫ســوابق املدعــى عليــه املرفقــة باملعاملــة علــى اللفــة رقــم (‬\n      ‫‪ ) 72.71.670.69.68‬املتضمنــة وجــود ثــاث ســوابق علــى املدعــى عليــه‬\n      ‫األولــى انتحــال شــخصية الغيــر وســرقة أمــوال والثانيــة ســرقة والثالثــة‬\n      ‫ا الســوابق‬  ‫انتحــال شــخصية رجــل أمــن وبعرضهــا عليــه أجــاب قائ ـ ً‬\n      ‫كلهــا صحيحــة وبســؤال املدعــي باحلــق اخلــاص عــن املالــك للذهــب‬\n\n\n‫‪119‬‬\n\f‫ا الذهــب تعــود ملكيتــه لــي هكــذا أجــاب وبســؤاله البينــة‬        ‫فأجــاب قائـ ً‬\n‫علــى دعــواه فيمــا يخــص كميــة الذهــب حيــث أنــه لــم يذكــر يف إقــرار‬\n‫املدعــى عليــه املصــدق شــرع ًا كميــة وعــدد الذهــب املســروق فأجــاب‬\n‫ا لــدي هــذان الشــاهدان وهمــا …ســعودي اجلنســية مبوجب الســجل‬                ‫قائـ ً‬\n‫املدنــي رقــم ‪ ...‬ســجل جنــران يف ‪1426/11/12‬ه ـ و… ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم …ســجل جنــران يف ‪1428/11/11‬ه ـ‬\n‫ا أشــهد‬  ‫وبســؤال عمــا لديهمــا مــن شــهادة أجــاب كل واحــد منهمــا قائـ ً‬\n‫هلل تعالــى أن زوجــة املدعــي باحلــق اخلــاص قــد حصلــت مــن أخواتهــا‬\n‫قيمتهمــا ‪ 1700‬ريــال وهمــا مــن ضمــن املســروقات كمــا أشــهد أن‬\n‫جميــع الذهــب املســروق ملــك ل…‪ ..‬وقــد جــرى تعديــل الشــاهدين مــن‬\n‫ال مــن …ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم …‬                 ‫قبــل ك ً‬\n‫ســجل جنــران يف ‪1415/7/19‬ه ـ و…ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم …ســجل جنــران يف ‪1418/3/12‬ه ـ كمــا أبــرز فاتــورة‬\n‫صــادرة مــن محــل ‪ .......‬للذهــب واملجوهــرات متضمنــة قيــام املدعــو ‪…..‬‬\n‫بشــراء اثنــن بناجــر نــوع كويتــي وثــاث خــوامت واثنــن عقــد ‪( .....‬واحــد‬\n‫كــف) أي سلســال يــدوي مببلــغ وقــدره اثنــان وأربعــون ألــف ريــال‬\n‫ســعودي وبطلــب اليمــن املكملــة مــن املدعــي باحلــق اخلــاص علــى دعــواه‬\n‫ا « أقســم بــاهلل العظيــم أنــه‬\n                                ‫اســتعد باحللــف ثــم أذنــا لــه وحلــف بــاهلل قائـ ً‬\n‫ُســرق منــي ذهــب عبــارة عــن خمــس خــوامت واثنــن تعليقــة وثنتــن مــن‬\n‫األســاور وسلســال يــدوي ( كــف ) وأن قيمتهــا ثالثــة وأربعــون ألــف‬\n‫وســبعمائة ريــال ســعودي هكــذا حلــف « ولطلــب البائــع يف محــل ‪...‬‬\n‫لســماع دعــواه فقــد رفعــت اجللســة ثــم يف جلســة أخــرى حضــر املدعــي‬\n‫العــام واملدعــي باحلــق اخلــاص واملدعــى عليــه ولــم يحضــر ممثــل محــل ‪...‬‬\n\n\n                                                                                          ‫‪120‬‬\n\f      ‫يف هــذه اجللســة وبســؤال املدعــي باحلــق اخلــاص عــن الشــخص الــذي‬\n      ‫ا‬‫كتبــت باســمه الفاتــورة التــي قدمهــا يف اجللســة املاضيــة فأجــاب قائـ ً‬\n      ‫الفاتــورة باســم عمــي … حيــث كان معــي وقــت شــراء الذهــب وألنــه‬\n      ‫كبيــر يف الســن فقــد مت تســجيلها باســمه وأنــا مــن دفــع قيمــة الذهــب‬\n      ‫كمــا أن الذهــب يف الفاتــورة املذكــورة لــي هكــذا أجــاب وبعــرض‬\n      ‫الصلــح علــى املدعــي باحلــق اخلــاص واملدعــى عليــه اصطلحــا فيمــا يخــص‬\n      ‫اخلامتــن فقــط علــى أن يلتــزم املدعــى عليــه بــأن يدفــع للمدعــي باحلــق‬\n      ‫اخلــاص مبلغ ـ ًا وقــدره ألــف ريــال وتظــل الدعــوى يف احلــق اخلــاص قائمــة‬\n      ‫فيمــا ســوى اخلامتــن هكــذا اصطلحــا ولطلــب حضــور املدعــو …‬\n      ‫ومخاطبــة الغرفــة التجاريــة بنجــران ملخاطبــة شــيخ الصاغــة لديهــم‬\n      ‫لتقديــر ثمــن الذهــب املبــن بالفاتــورة املقدمــة مــن املدعــي باحلــق اخلــاص‬\n      ‫يف اليــوم الــذي ســرق فيــه الذهــب فقــد رفعــت اجللســة الســاعة احلاديــة‬\n      ‫عشــر والربــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1433/9/11‬ه ـ‬\n      ‫فتحــت اجللســة الثالثــة الســاعة الثانيــة وفيهــا حضــر أطــراف الدعــوى‬\n      ‫كمــا أنــه لــم يردنــا جــواب الغرفــة التجاريــة بنجــران ملخاطبــة شــيخ‬\n      ‫الصاغــة لديهــم لتقديــر ثمــن الذهــب املبــن بالفاتــورة املقدمــة مــن‬\n      ‫املدعــي باحلــق اخلــاص يف اليــوم الــذي ســرق فيــه الذهــب وبســؤال املدعــي‬\n      ‫ا‬ ‫باحلــق اخلــاص عــن الشــخص الــذي كتبــت باســمه الفاتــورة أجــاب قائـ ً‬\n      ‫لــم أســتطع أن أحضــره يف هــذه اجللســة وســأحضره يف اجللســة‬\n      ‫القادمةكمــا أفــاد املدعــي باحلــق اخلــاص أنــه ال يطالــب محــل ‪...‬بإعــادة‬\n      ‫القطعــة التــي اشــتراها مــن املدعــى عليــه وأنــه يطالــب بقيمتهــا وأن‬\n      ‫مجمــوع مــا يطالــب بــه املدعــى عليــه بعــد الصلــح يف اجللســة املاضيــة هــو‬\n\n\n‫‪121‬‬\n\f‫ثالثــة وأربعــون ألــف ريــال وعليــه فقــد رفعــت اجللســة ثــم يف جلســة أخــرى‬\n‫حضــر أطــراف الدعــوى كمــا حضــر املدعــو ‪ ...‬ســعودي بالســجل املدني‬\n‫رقــم …ســجل جنــران يف ‪1387/6/22‬ه ـ وبســؤاله عــن الفاتــورة‬\n‫ا الفاتــورة‬    ‫املذكــورة يف دعــوى املدعــي باحلــق اخلــاص فأجــاب قائ ـ ً‬\n‫املذكــورة كتبــت باســمي وكل مــا ورد ذكــره فيهــا ملــك للمدعــي‬\n‫باحلــق اخلــاص …هكــذا أجــاب كمــا وردنــا كمــا وردنــا خطــاب أمــن‬\n‫منطقــة جنــران برقــم ‪ 14036‬يف ‪1433/10/21‬ه ـ وبرفقــه خطاب شــيخ‬\n‫طائفــة صاغــة الذهــب بنجــران … املتضمــن أن ســعر اجلــرام يف الفاتــورة‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬ ‫‪ 191.43‬فقــط الغيــر فبنـ ً‬\n‫واملدعــي باحلــق اخلــاص وإنــكار املدعــى عليــه مــا جــاء فيهمــا وملــا جــاء‬\n‫بإقــراره املصــدق شــرع ًا ورجوعــه عنــه مبجلس القضــاء بدعوى اإلكراه‬\n‫وال بينــة لديــه علــى ذلــك وملــا جــاء بإقــراره حتقيق ـ ًا بقيامــه بشــراء ربــع‬\n‫كيلــو مــن احلشــيش املخــدر بقصــد االســتعمال الشــخصي ورجوعــه‬\n‫عنــه مبجلــس القضــاء بدعــوى اإلكــراه وال بينــة لديــه علــى ذلــك وملــا‬\n‫جــاء يف احلديــث عــن عــروة عــن عائشــة رضــي اهلل عنهــا‪ -‬أن رســول ‪-‬اهلل‬\n‫صلى اهلل عليه وســلم‪ -‬قال ‪ ( :‬ادرؤوا احلدود عن املســلمني ما اســتطعتم‬\n‫فــإن وجــدمت للمســلم مخرج ـ ًا فخلــوا ســبيله فــإن اإلمــام ألن يخطــئ يف‬\n‫العفــو خيــر لــه مــن أن يخطــئ يف العقوبــة) أخرجــه الترمــذي يف اجلامــع‬\n‫‪ ، 318/2‬والبيهقــي يف الســن الكبــرى ‪ ، 238/8‬والــدار قطنــي يف‬\n‫الســن ‪ ، 324/2‬واحلاكــم يف املســتدرك ‪ 384/4‬وألنــه ال يقبــل الرجــوع‬\n‫عــن اإلقــرار فيمــا يتعلــق بحقــوق اآلدمــي ألن اإلقــرار مظهــر حلــق موجــود‬\n‫قبــل صــدور اإلقــرار قــال يف الكشــاف « وال يقبــل رجــوع املقــر عــن‬\n‫إقــراره إال فيمــا كان حــد ًا فأمــا حقــوق اآلدميــن وحقــوق اهلل التــي ال‬\n\n\n                                                                                         ‫‪122‬‬\n\f      ‫تــدرأ بالشــبهات كالــزكاة والكفــارات فــا يقبــل رجوعــه عنهــا»‬\n      ‫ينظــر كشــاف القنــاع ‪ 408/15‬كمــا قــال يف موضــع آخــر «ومــن أتلــف‬\n      ‫ولــو خطــأ أو ســهو ًا مــا ًال محترم ـ ًا لغيــره بغيــر إذنــه ضمنــه» ينظــر‬\n      ‫كشــاف القنــاع ‪ 302/9‬وملــا جــاء يف شــهادة الشــهود املعدلــن التعديــل‬\n      ‫الشــرعي وملــا جــاء يف الصلــح بــن املدعــي باحلــق اخلــاص واملدعــى عليــه‬\n      ‫فيمــا يخــص اخلامتــن املذكوريــن بدعــوى املدعــي باحلــق اخلــاص واملثبتــة‬\n      ‫بشــهادة الشــهود وألن مــا قــام بــه املدعــى عليــه فعــل محــرم شــرع ًا‬\n      ‫ومعاقــب عليــه نظام ـ ًا وفيــه اعتــداء علــى حقــوق اآلخريــن وملــا جــاء يف‬\n      ‫املــادة (‪ )3‬مــن نظــام اإلجــراءات اجلزائيــة ولســوابق املدعــى عليــه فقــد‬\n      ‫حكمنــا يف احلــق العــام مبــا يلــي ‪ :‬أوالً‪ :‬إدانــة املدعــى عليــه بســرقة ذهــب‬\n      ‫عبــارة عــن (‪)2‬تعليقــه و(‪)5‬خــوامت و(‪)2‬ســواره وسلســال يــدوي مــن بيــت‬\n      ‫املدعــو …ثانيـاً‪ :‬عــدم إدانــة املدعــى عليــه بشــراء ربع كيلو من احلشــيش‬\n      ‫املخــدر بقصــد االســتعمال الشــخصي وتعاطيــه لــه‪ .‬ثالث ـاً‪:‬رد طلــب‬\n      ‫املدعــي العــام إقامــة حــد الســرقة علــى املدعــى عليــه لرجوعــه عــن إقراره‬\n      ‫رابع ـاً‪ :‬رد طلــب املدعــي العــام تطبيــق العقوبــة الــواردة يف املــادة (‪)41‬‬\n      ‫والفقــرة األولــى مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات لعــدم‬\n      ‫إثبــات موجبــه‪ .‬خامسـاً‪ :‬تعزيــر املدعــى عليــه بســجنه ملــدة ســت ســنوات‬\n      ‫اعتبــار ًا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة وجلــده ســتمائة جلــدة‬\n      ‫مفرقــة علــى دفعــات مقــدار كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n      ‫وأخــرى ثالثــون يوم ـاً‪ .‬سادس ـاً‪ :‬تعزيــر املدعــى عليــه لقــاء توجــه التهمــة‬\n      ‫إليــه بشــراء ربــع كيلــو مــن احلشــيش املخــدر وتعاطيــه لــه بســجنه ملــدة‬\n      ‫ســنة وجلــده تســعون جلــدة مفرقــة علــى دفعتــن مقدار كل دفعة خمســة‬\n      ‫وأربعــون جلــدة بــن كل دفعــة وأخــرى ثالثــون يومـ ًا كمــا حكمنــا يف‬\n\n\n‫‪123‬‬\n\f‫احلــق اخلــاص بإلــزام املدعــى عليــه …بــأن يدفــع للمدعــي باحلــق اخلــاص‬\n‫…مبلغـ ًا وقــدره ثالثــة وأربعــون ألــف ريــال قيمــة املســروقات مــن الذهــب‬\n‫العائــد للمدعــي باحلــق اخلــاص وبعــرض ذلــك علــى أطــراف الدعــوى قــرر‬\n‫املدعــي باحلــق اخلــاص قناعتــه باحلكــم كمــا قــرر املدعى عليــه واملدعي‬\n‫العــام اعتراضهمــا علــى احلكــم بالئحــة اعتراضيــة فأفهمــا بــأن عليهمــا‬\n‫تقــدمي لوائحهمــا االعتراضيــة خــال مــدة قدرهــا ثالثــون يوم ـ ًا اعتبــار ًا‬\n‫مــن تاريــخ تســلمهما نســخة مــن القــرار ففهمــا ذلــك ورفعــت اجللســة‬\n‫الســاعة احلاديــة عشــر والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                 ‫وعلى آله وصحبه وسلم حرر يف ‪1434/3/3‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنني املوافــق ‪1434/7/17‬هـ وكانت‬\n‫املعاملــة قــد عــادت مــن محكمة االســتئناف بعســير برقــم ‪341336425‬‬\n‫يف ‪1434/7/11‬ه ـ وبرفقهــا قــرار التصديــق رقــم‪34245449‬يف‬\n‫‪1434/6/19‬ه ـ ونــص احلاجــة منــه ( وبدراســة القــرار الشــرعي وصــورة‬\n‫ضبطــه و الالئحــة االعتراضيــة و أوراق املعاملــة تقــررت املوافقــة علــى‬\n‫احلكــم ) واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف … ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف…ختمه وتوقيعــه قاضــي … ختمــه وتوقيعــه قاضــي اســتئناف‬\n‫…ختمــه وتوقيعــه رئيــس الدائــرة …ختمــه وتوقيعــه‪ .‬وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/17‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪124‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":111,"source_page_end":124,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d7de2b9a7346f587489e20dd265a9ea07c1a2886dc6cd54704b2c7612abb6f2d","normalized_text_hash":"ad50624a2ade3ecd2ee2f91c43dd9d2b330c7b2daafb770dee89920cd6083009","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p111-3457976"},{"id":"ef421c55-3e6b-59a5-8812-6f1fba04b572","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -شروع يف السرقة -مراقبة يف سرقة -تعزير بالسجن واجللد -تشديد العقوبة النتشار اجلرمية.","document_number":"34665919","case_number":"3440115","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بزيادة التعزير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/18","year":"1434","subject":"سرقة -شروع يف السرقة -مراقبة يف سرقة -تعزير بالسجن واجللد -تشديد العقوبة النتشار اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34665919 :‬تاريخه ‪1434/3/18 :‬هـ‬\n                            ‫رقم الدعوى‪3440115 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34274677‬تاريخه ‪1434/7/22 :‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬شــروع يف الســرقة ‪ -‬مراقبة يف ســرقة ‪ -‬تعزير بالســجن واجللد‬\n                                      ‫‪ -‬تشــديد العقوبة النتشــار اجلرمية‪.‬‬\n\n\n\n\n                     ‫‪-1‬قول اهلل تعالى ‪(:‬وال تعتدوا إن اهلل ال يحب املعتدين)‪.‬‬\n                       ‫‪-2‬قوله تعالى ( وال تفسدوا يف األرض بعد إصالحها )‪.‬‬\n      ‫‪-3‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                                     ‫ومالــه وعرضــه)‬\n      ‫‪-4‬قولــه صلــى اهلل عليــه وســلم (فــإن أموالكــم ودماءكــم وأعراضكــم‬\n      ‫عليكــم حــرام كحرمــة يومكــم هــذا يف شــهركم هــذا يف بلدكــم هذا)‪.‬‬\n      ‫‪-5‬مــا قــرره أهــل العلــم أن الســراق اذا اشــتركوا يف ســرقة وقــام أحدهــم‬\n      ‫بهتــك احلــرز واآلخــر قــام بإخــراج املســروق أنــه الحــد عليهمــا قــال يف‬\n      ‫كشــاف القنــاع ( وإن نقــب أحدهمــا ودخــل اآلخــر فأخرجــه فــا قطــع‬\n         ‫عليهمــا ولــو تواطــا ألن األول لــم يســرق والثانــي لــم يهتــك احلــرز)‪.‬‬\n\n\n\n\n‫‪125‬‬\n\f‫الئحــة الدعــوى ضــد املدعــى عليهمــا بتوجيــه االتهــام لــأول باالشــتراك‬\n‫مــع آخريــن يف الشــروع بســرقة مــن بقالــة بعــد كســر البــاب واشــتراك‬\n‫الثانــي باملراقبــة أثنــاء الشــروع يف الســرقة ‪ ،‬مت القبــض علــى املدعــى‬\n‫عليهمــا بعــد بــاغ عــن تعــرض بقالــة للســرقة وكســر القفــل اخلارجــي‬\n‫لهــا وباســتجوابهما أقــرا مبــا نســب إليهمــا‪ ،‬واعتــرف املدعــى عليهمــا‬\n‫‪ ،‬لــذا حكمــت احملكمــة بتعزيــر املدعــى عليهمــا بالســجن واجللــد‬\n‫‪ ،‬ووجهــت محكمــة االســتئناف بزيــادة التعزيــر‪ ،‬واســتجاب حاكــم‬\n             ‫القضيــة‪ ،‬ومت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ النبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬‫أنا‪.........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 1093‬وتاريخ‪1434/01/21‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪34196484‬وتاريخ‪1434/01/24‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس بقم‪3440115‬وتاريخ‪1434/01/24‬ه ـ فتحــت اجللســة األولــى‬\n‫يــوم االثنــن ‪1434/03/16‬ه ـ الســاعة العاشــرة والنصــف صباحـ ًا وفيهــا‬\n‫حضــر املدعــي العــام ‪.........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫ال‬\n‫األحســاء ذي الرقــم ‪.........‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ً‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظة األحســاء أدعي‬   ‫‪ :‬فبصفتــي مدعيـ ًا ً‬\n                                                                                    ‫‪126‬‬\n\f      ‫علــى كل مــن ‪ 18 ،......... 1:‬عامـ ًا ‪ ،‬غيــر محصــن ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ، ).........‬متســبب ‪ ،‬أوقــف بتاريــخ ‪8 / 17‬‬\n      ‫‪1433 /‬هـ ‪ ،‬وأفرج عنه بتاريخ ‪1433 / 12 / 18‬هـ بالكفالة اســتنا ًدا‬\n      ‫للمــادة ( ‪ ) 120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬يســكن األحســاء ‪-‬‬\n      ‫قريــة ‪ 21 ،......... - 2..........‬عام ـ ًا ‪ ،‬غيــر محصــن ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ، ).........‬متســبب ‪ ،‬أوقــف بتاريــخ ‪8 / 14‬‬\n      ‫‪1433 /‬هـ ‪ ،‬وأفرج عنه بتاريخ ‪1433 / 12 / 18‬هـ بالكفالة اســتنا ًدا‬\n      ‫للمــادة ( ‪ ) 120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬يســكن األحســاء ‪-‬‬\n      ‫قريــة ‪..........‬إنــه بتاريــخ ‪ 1433 / 7 / 15‬ه ـ ورد بــاغ للدوريــات األمنيــة‬\n      ‫مــن املواطــن ‪......... /‬عــن تعــرض احملــل اخلــاص بــه ( بقالــة ‪).........‬‬\n      ‫الواقعــة بقريــة ‪.........‬لكســر القفــل اخلارجــي وكســر البــاب الزجاجــي‬\n      ‫‪ ،‬وســرقة مبلــغ مالــي وقــدره ( ‪ ) 600‬ســتمائة ريــال ‪ ،‬ومحاولــة ســرقة‬\n      ‫مــواد غذائيــة ‪ ،‬ولكــن لــم يحملوهــا معهــم حيــث تركوهــا يف احملــل‬\n      ‫بعدمــا قامــوا بجمعهــا يف كيــس ‪ ،‬وال يتهــم أحـ ًـدا بذلــك وبانتقــال‬\n      ‫ومعاينــة املوقــع اتضــح بأنــه عبــارة عــن بقالــة ‪.........‬تقــع بقريــة ‪.........‬‬\n      ‫داخــل احلــي الســكني اجلديــد ‪ ،‬وتفتــح باجتــاه الشــمال ‪ ،‬ومــن خــال‬\n      ‫املعاينــة اخلارجيــة للموقــع اتضــح أن البــاب اخلارجــي للبقالــة مفتــوح عنــوة‬\n      ‫والقفــل غيــر موجــود ‪ ،‬كمــا لوحــظ البــاب الزجاجــي للبقالــة متعــرض‬\n      ‫للكســر بواســطة حجــر كبيــر ‪ ،‬كمــا شــوهد كيــس أســود بــه مــواد‬\n      ‫غذائيــة وبطاقــات شــحن وعلــب دخــان داخــل احملــل يحتمــل أن اجلنــاة‬\n      ‫قامــوا بوضــع املســروقات فيــه ولــم يتمكنــوا مــن الهــروب بهــا ‪.‬وبضبــط‬\n      ‫أن احملــل اخلــاص بــه ( بقالــة ‪ ).........‬الواقعــة‬\n                                                           ‫أقــوال املدعــي ‪......... /‬أفــاد َّ‬\n      ‫بقريــة ‪.........‬تعرضــت لكســر القفــل اخلارجــي وكســر البــاب الزجاجــي‬\n\n\n‫‪127‬‬\n\f‫‪ ،‬وســرقة مبلــغ مالــي وقــدره ( ‪ ) 600‬ســتمائة ريــال ‪ ،‬ومحاولــة ســرقة‬\n‫مــواد غذائيــة ولكــن لــم يحملوهــا معهــم حيــث تركوهــا يف احملــل‬\n‫بعدمــا قامــوا بجمعهــا يف كيــس أســود ‪ .‬وباســتجواب املدعــى عليــه‬\n‫ال مــن ‪.........‬و‪ ( .........‬فــرزت لهمــا‬\n                                         ‫األول أقــر بأنــه كان رفــق زمالئــه ك ً‬\n‫أوراق مســتقلة كونهمــا حدثــن ) مــع املدعــى عليــه الثانــي يف أرض‬\n‫فضــاء قــرب بقالــة النخيــل مــن أجــل التخطيــط لســرقة البقالــة حيــث‬\n‫توجهــوا إليهــا ‪ ،‬وقــام بكســر القفــل اخلارجــي بواســطة قطــع حديــد‬\n‫مــن مخالفــات البنــاء ومــن ثــم املراقبــة رفــق زميلــه الثانــي مــن اخلــارج ‪،‬‬\n‫ثــم قــام املدعــو ‪......... /‬بكســر زجــاج البــاب الداخلــي والدخــول برفــق‬\n‫‪ ،......... /‬والســرقة مــن البقالــة ثــم شــاهدوا أحــد جيــران البقالــة يخــرج‬\n‫ـرعا بذلــك ‪.‬وباســتجواب‬    ‫مــن منزلــه والذوا بالفــرار ؛ وصــدق إقــراره شـ ً‬\n‫وأن دوره كان‬   ‫املدعــى عليــه الثانــي أقــر مبثــل مــا أقـ َّـر بــه األول ‪َّ ،‬‬\n‫ـرعا بذلــك ‪.‬وقــد أســفر التحقيــق معهمــا عــن‬  ‫املراقبــة ؛ وصــدق إقــراره شـ ً‬\n‫توجيــه االتهــام لــأول باالشــتراك رفــق آخريــن يف الشــروع بســرقة مــن‬\n‫بقالــة ‪.........‬بعــد كســر البــاب واشــتراك الثانــي باملراقبــة أثنــاء الشــروع‬\n‫يف الســرقة؛ وذلــك لألدلــة والقرائــن التاليــة ‪ - 1:‬إقرارهمــا املصــدق‬\n‫ـرعا املنــوه عنــه ‪ ،‬واملــدون علــى صفحــة رقــم ( ‪ ) 15 , 12‬مــن دفتــر‬    ‫شـ ً‬\n‫التحقيــق لفــة رقــم ( ‪ , 2. ) 1‬محضــر االنتقــال واملعاينــة املنــوه عنــه ‪،‬‬\n‫واملــدون علــى صفحــة رقــم ( ‪ ) 3 , 2‬مــن دفتــر التحقيــق لفــة رقــم ( ‪17‬‬\n‫)‪ _ 3.‬مــا ورد يف أقــوال املب ِّلــغ املنــوه عنهــا ومطابقــة ذلــك ملــا ورد يف‬\n‫أقــوال املدعــى عليهمــا ‪ ،‬واملــدون علــى الصفحــة رقــم ( ‪ ) 10 , 9‬مــن‬\n‫دفتــر التحقيــق لفــة رقــم ( ‪. ) 17‬وبالبحــث عمــا إذا كان عليهمــا ســوابق‬\n‫لــم يعثــر لهمــا علــى ســوابق مســجلة حتــى تاريخــه وحيــث إن مــا أقدمــا‬\n\n\n                                                                                       ‫‪128‬‬\n\f      ‫عليــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا ؛ أطلــب إثبــات مــا أســند إليهمــا ‪ ،‬واحلكــم‬\n      ‫علمــا أن احلــق‬\n                     ‫عليهمــا بعقوبــة تعزيريــة رادعــة لهمــا وزاجــرة لغيرهمــا ‪ً (.‬‬\n      ‫اخلــاص انتهــى بالتنــازل ) هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى‬\n      ‫عليهمــا وبعــد التأكــد مــن هويتهمــا جــرى عــرض دعــوى املدعــي العــام‬\n      ‫ا ‪ :‬ماذكــره املدعــي‬         ‫عليهمــا فأجــاب املدعــى عليــه األول ‪.........‬قائ ـ ً‬\n      ‫العــام مــن اتهامــي باالشــتراك يف الشــروع بالســرقة مــن بقالــة ‪.........‬‬\n      ‫فصحيــح وكان دوري كســر قفــل البــاب بحديــدة وقــد قمــت بذلــك‬\n      ‫ثــم قمــت باملراقبــة وأنــا تائــب ونــادم علــى مــا بــدر منــي هكــذا أجــاب‬\n      ‫ا ‪ :‬ماذكــره املدعــي العــام‬        ‫كمــا أجــاب املدعــى عليــه الثانــي ‪.........‬قائـ ً‬\n      ‫مــن اتهامــي باالشــتراك يف ســرقة البقالــة املذكــورة فصحيــح وكان‬\n      ‫دوري يف ذلــك املراقبــة وأنــا تائــب إلــى اهلل هكــذا أجــاب ثــم جــرى‬\n      ‫االطــاع علــى جميــع أوراق املعاملــة ومنهــا كرتــي ســوابق املدعــى عليــه‬\n      ‫ـاء علــى ماتقــدم مــن الدعــوى‬       ‫املتضمنــن عــدم وجــود ســوابق عليهمــا فبنـ ً‬\n      ‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليهمــا والتأكــد مــن أهليتهمــا‬\n      ‫أن املدعــى عليــه األول ‪.........‬‬      ‫وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n      ‫أقـ َّـر بدعــوى املدعــي العــام وأ َّنــه قــام باالشــتراك رفــق آخريــن يف الشــروع‬\n      ‫بســرق ٍة مــن بقالــة ‪.........‬وقــام بكســر قفــل البــاب بحديــدة ولــم يدخــل‬\n      ‫أن الســراق إذا‬   ‫البقالــة وإمنــا ذهــب للمراقبــة وملــا قــرره أهــل العلــم مِ ــنْ َّ‬\n      ‫اشــتركوا يف ســرقة وقــام أحدهــم بهتــك احلــرز واآلخــر قــام بإخــراج‬\n      ‫املســروق أ َّنــه ال حـ َّـد عليهمــا قــال يف كشــاف القنــاع ‪( :‬وإن نقــب‬\n      ‫ألن األول‬ ‫أحدهمــا ودخــل اآلخــر فأخرجــه فــا قطــع عليهمــا ولــو تواطــآ َّ‬\n      ‫أن املدعــى عليــه الثانــي‬     ‫لــم يســرق والثانــي لــم يهتــك احلــرز) ا‪.‬ه ـ ومبــا َّ‬\n\n‫‪129‬‬\n\f‫‪.........‬أقـ َّـر بدعــوى املدعــي العــام مــن اتهامــه باالشــتراك يف املراقبــة‬\n‫أثنــاء الشــروع يف ســرقة البقالــة املذكــورة وملــا قــرره أهــل العلــم مــن‬\n‫أن مــا صــدر منهمــا مِ ــنْ احملـ َّـرم شــرع ًا قــال‬   ‫أن ردء الســارق اليحـ ُّـد ومبــا َّ‬        ‫َّ‬\n‫اهلل تعالــى ‪ { :‬وال تعتــدوا إن اهلل ال يحــب املعتديــن } وقــال تعالــى ‪:‬‬\n‫ض َب ْعـ َـد ِإ ْصالَحِ َهــا} وقــال صلــى اهلل عليــه وســلم‬       ‫األر ِ‬      ‫{و َال ُت ْف ِسـ ُـد ْ‬\n                                                                           ‫وا ِف ْ‬                   ‫َ‬\n‫‪( :‬كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه) وقــال‪( :‬فــإن‬\n‫أموالكــم ودماءكــم وأعراضكــم عليكــم حــرام كحرمــة يومكــم‬\n‫هــذا يف شــهركم هــذا يف بلدكــم هــذا ) ممــا يســتوجب معــه تعزيــر‬\n‫املدعــى عليهمــا ويتوجــه تشــديد العقوبــة عليهمــا خلطــورة ماصــدر منهمــا‬\n‫أيضــا ‪ -‬أن يكــون املدعــى عليه األول‬           ‫والنتشــار الســرقة كمــا يتوجــه ‪ً -‬‬\n‫أشـ َّـد عقوبــة مــن الثانــي لعظــم ماصــدر منــه لــذا كلــه وألجــل احلــق العــام‬\n‫ـدي إدانــة املدعــى‬ ‫حكمــت علــى املدعــى عليهمــا مبــا يلــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n‫عليــه األول ‪.........‬باالشــتراك رفــق آخريــن يف الشــروع بســرق ٍة مــن بقالــة‬\n‫‪.........‬والقيــام بكســر قفــل البــاب بحديــدة وهــذه ســرقة غيــر مكتملــة‬\n‫الشــروط وعزرتــه لقــاء ذلــك بســجنه ملــدة عــام حتتســب منهــا املــدة التــي‬\n‫أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائتــان وخمســون جلــدة مفرقــة‬\n‫علــى خمــس دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى‬\n‫ـدي إدانــة املدعــى عليــه الثاني‬     ‫مــدة ال تقــل عــن عشــرة أيــام‪ .‬ثانيـ ًا ‪ /‬ثبــت لـ َّ‬\n‫‪.........‬باالشــتراك يف املراقبــة أثنــاء الشــروع يف ســرقة البقالــة املذكــورة‬\n‫وعزرتــه لقــاء ذلــك بســجنه ملــدة ســتة أشــهر حتتســب منهــا املــدة التــي‬\n‫أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n‫متســاويتني كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة‬\n‫التقــل عــن عشــرة أيــام ‪ .‬ثالثـ ًا ‪ /‬يؤخــذ عليهمــا التعهــد بعــدم العــودة ملثــل‬\n\n\n                                                                                                            ‫‪130‬‬\n\f      ‫مــا صــدر منهمــا ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليهما‬\n      ‫بحقهمــا يف التمييــز قــررا قناعتهمــا باحلكــم وطلــب املدعــي العــام رفــع‬\n      ‫احلكــم للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة الدعــوى وأقفلــت‬\n      ‫اجللســة الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف ‪1434/03/18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ‪:‬‬\n      ‫ففــي يــوم الثالثــاء ‪1434/06/20‬ه ـ فتحــت اجللســة الثالثــة الســاعة‬\n      ‫الواحــدة والربــع وفيهــا حضــر الطرفــان وقــد عــادت املعاملــة املتعلقــة‬\n      ‫بالدعــوى العامــة ضــد ‪.........‬ورفيقــه مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم‪34/1084392‬‬\n      ‫وتاريــخ ‪1434/06/13‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة األولــى(ج‪)1/‬‬\n      ‫رقم‪34232637‬وتاريخ‪1434/06/06‬ه ـ املتضمــن مــا نصــه‪« :‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن مــا حكــم بــه فضيلتــه‬\n      ‫علــى املدعــى عليهمــا قليــل جــد ًا لتكــرر جرائــم الســرقة يف أوســاط‬\n      ‫الشــباب وإلقــرار املدعــى عليهمــا بفعلهــا ممــا يســتوجب زيــادة تعزيرهمــا‬\n      ‫تعزيــر ًا بليغـ ًا حتــى يكونــا عبــرة للغيــر ملالحظــة ذلــك وإكمــال الــازم‬\n      ‫ومــن ثــم إعــادة املعاملــة واهلل املوفــق « ا‪.‬ه ـ عليــه أجيــب مشــايخي نفعنــي‬\n      ‫ـأن ماذكــروه وجيــه وعليــه وخلطــورة مــا أقدمــا عليــه‬     ‫اهلل بعلمهــم ‪ :‬بـ َّ‬\n      ‫عمــا حكمــت بــه علــى املدعــى عليهمــا‬‫والنتشــار الســرقات فقــد رجعــت َّ‬\n      ‫يف الفقرتــن أو ًال وثاني ـ ًا مــن تعزيــر وعــزرت املدعــى عليــه األول ‪.........‬‬\n      ‫بســجنه ملــدة ســنة وســتة أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا‬\n      ‫علــى ذمــة القضيــة وبجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات‬\n      ‫كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة التقــل عــن‬\n\n\n‫‪131‬‬\n\f‫عشــرة أيــام ‪ .‬وبتعزيــر املدعــى عليــه الثانــي ‪.........‬بســجنه ملــدة عــام‬\n‫حتتســب منهــا املــدة التــي أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائتــا‬\n‫جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة وبــن كل‬\n‫دفعــة وأخــرى مــدة التقــل عــن عشــرة أيــام ‪ .‬وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــى عليهمــا القناعــة بــه والزال املدعــي العــام علــى مــا‬\n‫ـرت بالتهميــش علــى قــرار احلكــم مبــا طــرأ عليــه ومــن ثـ ّـم‬ ‫هــو عليــه وأمـ ُ‬\n‫إعــادة املعاملــة حملكمــة االســتئناف باملنطقــة الشــرقية لتدقيــق احلكــم‬\n‫وأقفلــت اجللســة الســاعة الواحــدة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه أجمعــن ُحـ ِـر َر يف‪1434/06/20‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء‬\n‫املكلــف برقــم ‪ 34/1084292‬وتاريــخ ‪1434/6/26‬ه ـ املقيــدة لــدى‬\n‫احملكمــة برقــم ‪ 341599681‬وتاريــخ ‪1434/7/2‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.........‬املســجل برقــم‬\n‫‪ 34165919‬وتاريــخ ‪1434/3/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫ضــد‪.........-2.........-1/‬يف قضيــة ســرقه وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬حيث ســبق دراســة القــرار وصورة‬\n‫ضبطــه وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار‬\n‫وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‪ 34232637‬يف ‪1434/6/6‬ه ـ‬\n‫قررنــا املصادقــة علــى ماحكــم بــه فضيلتــه أخيــرا واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/7/19‬ه ـ ‪.‬‬\n\n\n\n                                                                                         ‫‪132‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":125,"source_page_end":132,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2fec357487e9fbb58231b1a336479b38698e77fe166294877ee166b88aba2be7","normalized_text_hash":"747ee8ac6dd90400397903d4d4b717d8994278ae510c9ededa802941e7e762ff","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p125-34665919"},{"id":"89c02bd8-c330-527c-ae7c-ab80762fcf39","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -نهب -ال قطع على منتهب -ثبوت إدانة -تعزير بالسجن واجللد -رد دعوى املدعي العام بالتسبب يف إصابة لعدم كفاية","document_number":"3440354","case_number":"33516801","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/18","year":"1434","subject":"سرقة -نهب -ال قطع على منتهب -ثبوت إدانة -تعزير بالسجن واجللد -رد دعوى املدعي العام بالتسبب يف إصابة لعدم كفاية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3440354 :‬تاريخه‪1434/02/18 :‬هـ‬\n                           ‫رقم الدعوى‪33516801 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34277728‬تاريخه ‪1434/7/24 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬نهــب ‪ -‬ال قطــع علــى منتهــب ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n      ‫واجللــد ‪ -‬رد دعــوى املدعــي العــام بالتســبب يف إصابــة لعــدم كفايــة‬\n                                                                          ‫األدلــة‪.‬‬\n\n\n\n                              ‫ما رواه أبو داود مرفوع ًا ( ال قطع على منتهب )‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه باالحتيــال وســرقة جوالــن والتســبب‬\n      ‫بإصابــة شــخص‪ ،‬حيــث تقــدم أحــد املقيمــن ببــاغ ملركــز الشــرطة‬\n      ‫مفيــد ًا أنــه يف متــام الســاعة الثامنــة مســاء وأثنــاء وقوفــه أمــام املســجد‬\n      ‫إذا بشــخص طويــل القامــه نحيــف البنيــه يرتــدي شــماغ ًا لونــه أحمــر‬\n      ‫يركــب ســيارة صغيــرة قــام بالوقــوف بجانبــه والتحــدث معــه وســؤاله‬\n      ‫هــل تبحــث عــن عمــل ثــم قــام بســحب جوالــه ‪،‬وقــد طلــب املدعــي العــام‬\n      ‫إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره‬\n      ‫وتــردع غيــره‪ ،‬وأقــر املدعــى عليــه مبــا نســب إليــه ‪ ،‬وذكــر املدعــى عليــه‬\n      ‫أن احلاجــة أجلأتــه لذلــك ‪ ،‬لــذا صــدر احلكــم بتكييــف ســرقة اجلوالــن‬\n      ‫علــى أنهــا انتهــاب وال قطــع علــى منتهــب ‪ ،‬وتقــرر تعزيــر املدعــى عليــه‬\n                  ‫بالســجن واجللــد ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪133‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 33516801‬وتاريــخ ‪ 1433/08/11‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331504744‬وتاريــخ ‪ 1433/08/11‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق‪ 1434/02/11‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ...‬مبوجــب التكليــف الصــادر مــن هيئــة‬\n‫التحقيــق واالدعــاء العــام بنجــران رقــم ه ـ ن ‪ 11178/2/1‬بتاريــخ‬\n‫‪1430/12/29‬ه ـ وادعــى علــى احلاضــر معــه مينــي اجلنســية مبوجــب‬\n‫رخصــة االقامــة رقــم (‪ )......‬قائــا يف دعــواه عليــه حيــث إنــه ورد يف‬\n‫محضــر الدوريــات رقــم (‪ )1021‬وتاريــخ ‪1433/7/15‬ه ـ تلقيهــم بالغـ ًا‬\n‫عــن ســيارة مــن نــوع قــام قائدهــا بضــرب أحــد العمــال وســرقة جوالــه‬\n                                                      ‫والهــروب مــن املوقــع‪.‬‬\n‫وبتاريــخ ‪1433/7/15‬ه ـ تقــدم ‪ ........./‬ببــاغ ملركــز شــرطة اخلالديــة‬\n‫مفيــدا أنــه تعــرض لســرقة جوالــه نــوع (…) مــن قائــد ســيارة نوعهــا‬\n‫‪ .............‬يســتقلها شــخصان ‪ ،‬وقــام بأخــذ اجلــوال منــه ‪ ،‬وأثنــاء ســير‬\n                                                         ‫الســيارة ســقط بالطريــق‪.‬‬\n‫وبتاريــخ ‪1433/7/15‬ه ـ تقــدم‪ ............. /‬ببــاغ ملركــز شــرطة اخلالديــة‬\n‫مفيــد ًا أنــه يف متــام الســاعة الثامنــة مــن مســاء يــوم الثالثــاء املوافــق‬\n‫‪1433/7/15‬ه ـ وأثنــاء وقوفــه أمــام مســجد ‪ ..........................‬مــن جهــة‬\n‫اجلنــوب إذا بشــخص طويــل القامــة نحيــف البنيــة يرتــدي شــماغ ًا لونــه‬\n‫أحمــر ‪ ،‬وكان يركــب ســيارة صغيــرة لونهــا ‪ ............‬ال يعــرف رقــم‬\n\n                                                                                      ‫‪134‬‬\n\f      ‫لوحتهــا يقــف بجانبــه وقــام بالتحــدث معــه بســؤاله هــل تبحــث عــن شــغل‬\n      ‫ثــم قــال لــه ال أريــد ثــم قــال لــه يوجــد لديــه بقالــة وســوف يقــوم بتوظيفــه‬\n      ‫فيهــا وإعطائــه راتــب شــهري قــدره (‪)1700‬ألــف وســبعمائة ريــال‪ ،‬ويريــد‬\n      ‫رقــم جوالــه فســحب جوالــه نــوع(…) ‪ .............‬اللــون مــن يديــه واجتــه‬\n                                                                  ‫مســرع ًا باجتــاه الشــرق‪.‬‬\n      ‫وقــد مت إعــداد محضــر مواجهــة مــن قبــل مركــز شــرطة اخلالديــة ‪ ،‬بــن‬\n         ‫املتهــم‪ ............. /‬والوافــد‪ ............. /‬ومت التعــرف عليــه وعلــى ســيارته ‪.‬‬\n      ‫ومت إعــداد تقريــر طبــي أولــي رقــم (بــدون) وتاريــخ ‪1433/7/15‬ه ـ‬\n      ‫بشــأن‪ ،............. /‬مفيــد ًا أن االصابــة لــم تكــن مــن آلــة حــادة‪ ،‬ومــدة‬\n                                                          ‫الشــفاء أقــل مــن ســبعة أيــام ‪.‬‬\n      ‫وقــد مت إعــداد محضــر مواجهــة مــن قبــل مركــز شــرطة اخلالديــة بــن‬\n      ‫املتهــم‪ ............. /‬والوافــد‪ ............. /‬ومت التعــرف عليــه وأنــه مــن قــام‬\n                                                                             ‫بســلبه جوالــه‪.‬‬\n      ‫مت اإلفــراج عــن املتهــم‪ ............./‬املذكــور اســتناد ًا للمــادة(‪ )120‬مــن‬\n                                                             ‫نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫وبســماع أقــوال املدعــي األول‪ ............. /‬أفــاد بأنــه أثنــاء تواجــده خلــف‬\n      ‫مستشــفى ‪ .............‬قدمــت باجتاهــه ســيارة مــن نــوع ‪ .............‬وفيهــا‬\n      ‫شــخصان وقــام الســائق بطلبــه البحــث لــه عــن أحــد العمــال لكــي يعمــل‬\n      ‫لديــه‪ ،‬وطلــب منــه اجلــوال نــوع (…) ‪ .............‬اللــون فأعطــاه إيــاه وحــاول‬\n      ‫التحــرك مــن املــكان فأمســك بيــده ولكــن ألقــاه بالطريــق والســيارة‬\n                                                                             ‫تســير وهــرب‪..‬‬\n      ‫وبســماع أقــوال املدعــي الثانــي‪ ............. /‬أفــاد بأنــه يف متــام الســاعة‬\n      ‫الثامنــة مــن مســاء يــوم الثالثــاء املوافــق ‪1433/7/15‬ه ـ وأثنــاء وقوفــه‬\n\n\n‫‪135‬‬\n\f‫أمــام مســجد خــادم احلرمــن الشــريفني مــن جهــة اجلنــوب إذا بشــخص‬\n‫طويــل القامــة نحيــف البنيــة يرتــدي شــماغا لونــه أحمــر‪ ،‬وكان يركــب‬\n‫ســيارة صغيــرة لونهــا ‪ .............‬ال يعــرف رقــم لوحتهــا يقــف بجانبــه وقــام‬\n‫بالتحــدث معــه بســؤاله هــل تبحــث عــن شــغل ثــم قــال لــه ال أريــد‪ ،‬ثــم قال‬\n‫لــه يوجــد لديــه بقالــة وســوف يقــوم بتوظيفــه فيهــا وإعطائــه راتــب شــهري‬\n‫قــدره (‪ )1700‬ألــف وســبعمئة ريــال‪ ،‬ويريــد رقــم جوالــه فســحب جوالــه‬\n      ‫نــوع(…) ‪ .............‬اللــون مــن يديــه واجتــه مســرع ًا باجتــاه الشــرق ‪.‬‬\n‫وبســماع أقــوال املتهــم‪ ............. /‬أنكــر قيامــه بالســرقة وال يعــرف‬\n‫شــيئ ًا عــن املوضــوع وباســتجواب املتهــم‪ ............. /‬أقــر بقيامــه بســرقة‬\n‫جوالــن األول‪ ............. )…( /‬اللــون‪ ،‬وأنــه كان مــار ًا خلــف مستشــفى‬\n‫‪ ،.............‬وشــاهد أحــد الوافديــن وتوقــف بجــواره وحتــدث معــه بأنــه‬\n‫يريــده أن يعمــل معــه يف محــل جواالت‪،‬فقــال‪/‬ال أســتطيع‪ ،‬فقــال لــه‬\n‫ســجل رقمــي لديــك إذا وجــدت شــخص يريــد أن يعمــل معــي فأخبرنــي‪،‬‬\n‫فأخــرج جوالــه لتســجيل الرقــم فأخذ(املتهــم) اجلــوال لكــي يســجل لــه‬\n‫الرقــم وهــرب مــن املوقــع باجتــاه طريــق ‪ ،.............‬وكان يرافقــه ابــن‬\n‫خالــه ‪ ،‬واجلــوال الثانــي مــن نــوع (…) ‪ .............‬اللــون ‪ ،‬وأفــاد أنــه كان‬\n‫متواجــد ًا خلــف جامــع ‪ ..........................‬وشــاهد أحــد الوافديــن لوحــده‬\n‫ودعــاه وعــرض عليــه العمــل معــه يف بقالــه‪ ،‬ولكنــه رفــض ‪ ،‬فقــال لــه‬\n‫ســجل رقمــي لديــك‪ ،‬فســجل (الوافــد) الرقــم فطلــب (املتهــم) اجلهــاز‬\n                          ‫ليتأكــد مــن الرقــم‪ ،‬ثــم حــرك ســيارته مباشــرة ‪.‬‬\n‫وانتهــى التحقيــق إلــى توجيــه اإلتهــام لـ ـ ‪ ............./‬باالحتيــال وســرقة‬\n‫جوالــن األول ( …)‪ .............‬اللــون والثانــي (… )‪ .............‬اللــون‪،‬‬\n                                                  ‫والتســبب يف إصابــة شــخص‪.‬‬\n\n\n                                                                                        ‫‪136‬‬\n\f                                                        ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬إقــرار املتهــم املنــوه عنــه املــدون علــى ص(‪ )8-7-4-3‬مــن دفتــر‬\n                                                         ‫التحقيــق املرفــق لفــة (‪. )27‬‬\n      ‫‪ -2‬مــا جــاء يف محضــر املواجهــه املنــوه عنــه علــى ص(‪ )5-8‬مــن دفتــري‬\n                                                   ‫االســتدالل املرفقــان لفــة (‪. )21-1‬‬\n      ‫‪ -3‬مــا جــاء يف محضــر الدوريــات األمنيــة املنــوه عنــه املــدون علــى لفــة‬\n                                                                                         ‫(‪. )3‬‬\n                   ‫‪ -4‬ما جاء يف التقرير الطبي املنوه عنه املدون على لفة (‪. )16‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املتهــم املذكــور وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا‬\n                 ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره‪.‬‬\n                               ‫(علم ًا بأن احلق اخلاص انتهى بالتنازل) هذه دعواي ‪.‬‬\n      ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n      ‫املدعــي يف دعــواه مــن احتيالــي لســرقة جوالــن األول مــن نــوع (…)‬\n      ‫‪ .............‬اللــون والثانــي مــن نــوع ( ‪ ............. ) ...‬اللــون هــذا غيــر صحيــح‬\n      ‫حيــث إن عنــدي محــل للجــواالت يف ســوق الفصليــة للجــواالت وحضــر‬\n      ‫عنــدي يف أحــد األيــام اثنــن وافديــن مــن اجلنســية الهنديــة فيمــا بعــد‬\n      ‫وطلبــا منــي اجلــواالت املذكــورة يف دعــوى فلمــا أحضرتهــا لهــم خرجــت‬\n      ‫مــن احملــل ألحضــر ذاكــرة ألحدهــم وحينمــا رجعــت لــم أجــد الوافديــن‬\n      ‫بعــد مــرور ســنة وجــدت أحــد الوافديــن الــذي أخــذ جــوال (…) وأردت‬\n      ‫االحتيــال عليــه حتــى أخــذ اجلــوال منــه فقلــت لــه أريــد منــك أن حتضــر‬\n      ‫لــي عامــل يشــتغل يف بقالــة عنــدي وقلــت لــه ســجل رقمــي عنــدك حتــى‬\n      ‫تتصــل بــي فلمــا أخــرج جوالــه أخذتــه منــه ووجــدت ذلــك الوافــد اآلخــر‬\n\n\n‫‪137‬‬\n\f‫الــذي أخــذ اجلــوال (…) وفعلــت بــه مثــل األول وأخذتــه منــه و واهلل أنــي‬\n‫مــا فعلــت ذلــك إال للحاجــة التــي اضطرتنــي لذلــك وكــون هــذا حقــي‬\n‫الــذي أخــذ منــي وقــد حصــل لــي حــادث يف ذلــك اليــوم وأمــا اإلصابــة‬\n‫التــي حلقــت بأحــد الوافديــن فــا أعلــم عنهــا وقــد تكــون بســبب أنــه‬\n‫ماســكا ملقبــض البــاب للســيارة فحصــل لــه احتــكاك بســببها هــذه‬\n                                                                        ‫إجابتــي ‪.‬‬\n‫وبســؤال املدعــي عــن ذلــك قــال غيــر صحيــح والصحيــح مــا ذكــرت‬\n‫ولــدي بينــة علــى ذلــك ثــم رفعــت لإلطــاع والتأمــل حتــى يوم غدا الســاعة‬\n‫التاســعة صباحــا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/02/12‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام كمــا حضــر املدعــى عليــه‬\n‫وجــرى منــا تأمــل ودراســة أوراق املعاملــة حيــث جــرى اإلطــاع علــى‬\n‫أقــوال املدعــى عليــه يف دفتــر التحقيــق املرفــق لفــة (‪ )27‬واملدونــة علــى‬\n‫ص (‪ )6،5،4،3‬فوجدنــا إقــراره حتقيقــا بســرقة جــوال مــن الوافــد‬\n‫كمــا وجدنــا إقــراره حتقيقــا بســرقة جــوال مــن الوافــد وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال ليــس لــدي ســوى مــا ذكرتــه يف اجللســة الســابقة‬\n‫‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬\n‫بطريقــة أخــذه للجــواالت مــن الوافديــن وهــي داللــة علــى احتيــال كمــا‬\n‫وأن إقــراره حتقيقــا بســرقة اجلوالــن مــن الوافديــن قرينــة قويــة توجــه لــه‬\n‫التهمــة باالحتيــال بســرقة اجلوالــن مــن الوافديــن ومــا دفــع بــه ال يقــوى‬\n‫علــى إســقاط التهمــة بحقــه وملــا كان تصــرف املدعــى عليــه يف أخــذ‬\n‫اجلــوال هــو علــى ســبيل النهــب وقــد تقــرر شــرعا بأنــه (ال قطــع علــى‬\n\n\n                                                                                     ‫‪138‬‬\n\f      ‫منتهــب) رواه أبــي داود مرفوعــا ‪ .‬وبنــاء علــى عــدم وجــود ســوابق جنائيــة‬\n      ‫علــى املدعــى عليــه وبنــاء علــى مــا ظهــر لــي مــن عالمــات التوبــة والنــدم‬\n      ‫وجلميــع مــا ســلف فقــد قــررت مــا يلــي ‪ /1 :‬ثبــت لــدي إدانــة املدعــى عليــه‬\n      ‫باالحتيــال بنهــب جوالــن األول مــن نــوع (…) والثانــي مــن نــوع (…) مــن‬\n      ‫اثنــن مــن الوافديــن وحكمــت بتعزيــره وذلــك بســجنه ملــدة ثالثــة أشــهر‬\n      ‫وجلــده ثمانــن جلــده علــى دفعتــن كل دفعــة أربعــون جلــده بــن كل‬\n      ‫دفعــة واألخــرى عشــرة أيــام ‪ /2 .‬رد دعــوى املدعــي العــام بالتســبب يف‬\n      ‫إصابــة شــخص لعــدم كفايــة األدلــة ‪ .‬وبعــرض احلكم علــى املدعى عليه‬\n      ‫قــرر اعتراضــه علــى احلكــم بالئحــة اعتراضيــة فأفهمتــه مبعلومــات‬\n      ‫االعتــراض فيمــا قــرر املدعــي العــام اعتراضــه بــدون الئحــة فأمــرت‬\n      ‫بتنظيــم قــرار يرفــق بــاألوراق ويرســل ل ــمحكمة االســتئناف بعســير‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم ‪ .‬حــرر يف ‪ 1434/02/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة اجلزائية بنجران‬\n      ‫ففــي يــوم اإلثنــن املوافــق‪ 1434/06/19‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 12:30‬وقــد عــادت لنــا املعاملــة مــن محكمة االســتئناف مبنطقة عســير‬\n      ‫برقــم ‪ 34652368‬وتاريــخ ‪1434/4/22‬ه ـ واملقيــدة بهــذه احملكمــة‬\n      ‫برقــم ‪ 341030651‬وتاريــخ ‪1434/4/27‬ه ـ وبرفقهــا القــرار الصــادر‬\n      ‫بشــأنها برقــم ‪ 34181549‬وتاريــخ ‪1434/4/8‬ه ـ ونــص احلاجــه منــه (‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن فضيلــة ناظر‬\n      ‫القضيــة أثبــت قيــام املدعــى عليــه بســرقة جوالــن وهــذا التعبيــر ال يســوغ‬\n      ‫واملتعــن أن يقــول ثبــت لــدي قيــام املدعــى عليــه بنهــب جوالــن حتــى يتفــق‬\n      ‫حتــى يتفــق مــع العقوبــة وال بــد مــن ذلــك فعلــى فضيلتــه مالحظــة مــا‬\n\n\n‫‪139‬‬\n\f‫ذكــر وإكمــال مــا يلــزم نحــوه ومــن ثــم تعــاد املعاملــة إلكمــال الزمهــا‪.‬‬\n‫قاضــي اســتئناف ‪ .............‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.............‬‬\n‫ختمــه وتوقيعــه رئيــس ‪ .............‬الدائــرة ختمــه وتوقيعــه) أ‪.‬ه ـ عليــه أجيب‬\n‫أصحــاب الفضيلــة بأنــه ولوجاهــة مــا ذكــروه جــرى تعديــل الــازم واهلل‬\n‫يحفظكــم وأمــرت بإرســال كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫بعســير إلكمــال الزمهــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الواردة من فضيلة رئيس احملكمة اجلزائية بنجران برقم ‪341030651‬‬\n‫وتاريــخ ‪1434/6/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n‫باحملكمــة الشــيخ ‪ ............. /‬برقــم وتاريــخ ‪1434/2/18‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد ‪( ............. /‬مينــي اجلنســية) يف قضيــة (ســرقة‬\n‫جوالــن) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار‬\n‫ـاء علــى قرارنــا رقــم وتاريــخ ‪1434/4/8‬ه ـ تقــررت‬        ‫وصــورة ضبطــه بنـ ً‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪140‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":133,"source_page_end":140,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"01742237a88452f02dfee81d0fa23eed5f1fb15727f1343c967f995e02775b56","normalized_text_hash":"6abfcd60a83986cecccaaee6bf0e6a4c1dbe57c2135d2350a12de6774ea9d8f3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p133-3440354"},{"id":"8c246834-2ee3-588b-85ea-8a8c255ea377","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة معدات ثقيلة -مشاركة يف سرقة -شراء معدات مسروقة -عدم ثبوت إدانة -صرف نظر عن دعوى .","document_number":"3436922","case_number":"3452140","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"سرقة -سرقة معدات ثقيلة -مشاركة يف سرقة -شراء معدات مسروقة -عدم ثبوت إدانة -صرف نظر عن دعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3436922:‬تاريخه‪1434/2/13:‬هـ رقم‬\n                                ‫الدعوى‪3452140:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                     ‫‪ 34205140‬تاريخه ‪1434/5/4:‬ه‬\n\n\n\n      ‫ســرقة ‪-‬ســرقة معــدات ثقيلــة‪ -‬مشــاركة يف ســرقة‪ -‬شــراء معــدات‬\n                   ‫مســروقة‪ -‬عــدم ثبــوت إدانــة‪ -‬صــرف نظــر عــن دعــوى ‪.‬‬\n\n\n\n                                                         ‫‪-1‬األصل براءة الذمة ‪.‬‬\n      ‫‪-2‬قــال العــز بــن عبدالســام (فــإن األصــل بــراءة ذمتــه مــن احلقــوق‬\n      ‫وبــراءة جســده مــن القصــاص واحلــدود والتعزيــرات وبراءتــه مــن‬\n      ‫االنتســاب إلــى شــخص معــن ومــن األقاويــل كلهــا واألفعــال بأســرها)‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه باملشــاركة يف ســرقة معــدات ثقيلــة‬\n      ‫عــن طريــق شــرائها‪،‬وقد وطلــب املدعــي العــام إثبــات مــا أســند إليــه‬\n      ‫واحلكــم بعقوبــة تعزيريــة‪ ،‬حيــث مت القبــض علــى املدعــى عليــه بعــد‬\n      ‫ورود بالغــات بســرقة معــدات قــام املذكــور بشــرائها حيــث وجــدت‬\n      ‫عنــد معرضــه‪ ،‬وأقــر املدعــى عليــه بشــراء املعــدات وإنــكاره بالعلــم‬\n      ‫بأنهــا مســروقة‪ ،‬لــذا قــررت احملكمــة عــدم وجــود بينــة للمدعــي العــام‬\n      ‫علــى علــم املدعــى عليــه بــأن املعــدات مســروقة‪ ،‬وعليــه فقــد تقــرر عــدم‬\n      ‫ثبــوت إدانــة املدعــى عليــه‪ ،‬وقضــت بصــرف النظــر عــن دعــوى املدعــي‬\n                        ‫العــام‪ ،‬ومت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪141‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بنجــران برقــم ‪ ......‬وتاريــخ ‪ 1434/02/02‬هـ املقيدة‬\n‫باحملكمــة برقــم ‪ ........‬وتاريــخ ‪ 1434/02/02‬ه ـ ففــي يــوم الســبت‬\n‫املوافــق‪ 1434/02/09‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 30‬بشــأن‬\n‫دعــوى املدعــي العــام ‪ ......‬واملكلــف مبهمــة اإلشــراف علــى مكتــب‬\n‫االدعــاء العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس فــرع هيئــة‬\n‫التحقيــق واالدعــاء العــام مبنطقــة ‪ ..........‬وتاريــخ ‪1430/12/29‬ه ـ ضــد‬\n‫‪ )30 ( ........‬عامـ ًا ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪) ......‬‬\n‫متعلــم‪ ،‬متــزوج‪ ، ....... ،‬يســكن يف حــي‪ .....‬مبنطقــة ‪، .....‬مفــرج عنــه‬\n                                    ‫بالكفالــة احلضوريــة املرفقــة لفــة(‪0)46‬‬\n                      ‫باملشاركة يف سرقة معدات ثقيلة عن طريق شرائها‪0‬‬\n‫حيــث إنــه بتاريــخ ‪1433/5/12‬ه ـ تقــدم ملركــز شــرطة ‪ ......‬بالريــاض‪/‬‬\n‫‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ).....‬املفــوض مــن‬\n‫مجموعــة ‪ ، ...‬مخبــرا عــن ســرقة معــدة نــوع ‪ .....‬حتمــل الرقــم الهيكلــي‬\n‫(‪ ..... )....‬صبــاح يــوم الثالثــاء املوافــق ‪1433/5/11‬ه ـ مــن أمــام محطــة‬\n‫التســهيالت علــى طريــق اخلــرج باجتــاه الشــمال وال يتهــم أحــدا بســرقتها‬\n‫وبتاريــخ ‪1433/4/27‬ه ـ تقــدم ‪ ....... /‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقــم (‪ ).....‬ملركــز شــرطة ‪ ......‬مفيــدا عــن تعــرض املعدة العائدة‬\n‫لــه نــوع ‪ ....‬حتمــل الرقــم الهيكلــي (‪ ... )......‬أثنــاء وقوفهــا بحــي ال‪ ،..‬وال‬\n                                                         ‫يتهــم أحــدا بســرقته ‪0‬‬\n\n                                                                                         ‫‪142‬‬\n\f      ‫وبتاريــخ ‪1433/5/2‬ه ـ تقــدم ملركــز شــرطة شــمال الدمــام باملنطقــة‬\n      ‫الشــرقية ‪ ..... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪)......‬‬\n      ‫مفيــدا عــن تعــرض املعــدة نــوع ‪ ......‬حتمــل الرقــم الهيكلــي (‪)........‬‬\n      ‫للســرقة أثنــاء وقوفهــا علــى الشــارع العــام‪ ،‬وال يتهــم أحــدا بســرقته‪0‬‬\n      ‫وبتاريــخ ‪1433/5/23‬ه ـ تقــدم ملركــز شــرطة ‪ ...... /.......‬ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ( ‪ ).......‬عــن تعــرض املعــدة نــوع‬\n      ‫‪ ......‬حتمــل الرقــم الهيكلــي (‪ )......‬أثنــاء وقوفهــا بحــي ‪ ......‬وال يتهــم‬\n      ‫أحــدا بســرقتها فتــم البحــث عــن املعــدات املســروقة واجلنــاة‪ ،‬ويف يــوم‬\n      ‫األربعــاء املوافــق ‪1433/5/26‬ه ـ توفــرت معلومــات عــن وجــود املعــدات‬\n      ‫املســروقة املبلــغ عنهــا وأخــرى مبعــرض ال‪ ....‬بــال‪ ،...‬فتــم االنتقــال‬\n      ‫للموقــع‪ ،‬حيــث مت العثــور علــى أربــع معــدات ‪ ،‬األولــى نــوع ‪ ......‬رقــم‬\n      ‫(‪ ).....‬والثانيــة نــوع ‪ .....‬رقــم (‪ ).......‬والثالثــة نــوع ‪ ......‬رقــم (‪ ).......‬والرابعة‬\n      ‫نــوع ‪ ......‬رقــم (‪ )......‬أمــام معــرض‪ ....... /‬للمعــدات الثقيلــة‪ ،‬ومبســاءلة‬\n      ‫صاحــب املعــرض عــن وجــود املعــدات أمــام معرضــه ذكــر أنــه حضــر‬\n      ‫شــخص وعرضهــا عليــه لشــرائها ‪ ،‬فتــم إعــداد كمــن لــه ومت القبــض‬\n      ‫عليــه واتضــح أنــه (‪ )..........‬فــرزت لــه أوراق مســتقلة( إلقامــة الدعــوى‬\n      ‫العامــة عليــه يف مقــر ســكنه) مبوجــب خطــاب ســعادة رئيــس دائــرة‬\n      ‫االدعــاء العــام مبنطقــة ‪ 0.......‬برقــم (‪ ).....‬وتاريــخ ‪1433/10/25‬هــ‪00‬‬\n      ‫ومت االنتقــال ألحــد معــارض الســيارات الثقيلــة بحــي ‪ ......‬فعثــر علــى‬\n                      ‫أربــع معــدات نــوع ‪ ........‬حتمــل أرقــام الهيــاكل التاليــة‪-:‬‬\n                                                         ‫(‪ ).....‬عائدة لشركة ‪...‬‬                  ‫‪.1‬‬\n                                     ‫‪ )......( -3‬عائدة لشركة ‪ ......‬للمقاوالت‪0‬‬\n                                                            ‫‪ )......( -4‬عائدة ل‪0......./‬‬\n\n\n‫‪143‬‬\n\f‫‪ ).....( -5‬واقفــة أمــام معــرض‪ ،......./‬لــم يعــرف مالكهــا‪ ،‬وعثــر‬\n‫علــى حفــار نــوع ‪ ......‬رقم (‪ ).....‬مســروق وباســتجواب املدعــى عليه‪......../‬‬\n‫عــن شــرائه أربــع معــدات نــوع ‪........‬وعرضهــا للبيــع علــى معــرض ‪......‬‬\n‫أفــاد بأنــه اتصــل بــه‪ ( ....... /‬فــرزت لــه أوراق مســتقلة) مبوجــب اخلطــاب‬\n‫اخلــاص باملتهــم( ‪ )......‬املذكــور أعــاه ‪،‬وأخبــره أنــه يوجــد لــدى‪..../‬‬\n‫املســجون بســجون ‪ .....‬معــدات للبيــع‪ ،‬وســيم شــحنها لنجــران فقــام‬\n                                                                       ‫بشــرائها ‪0‬‬\n‫وقــد انتهــى التحقيــق بتوجيــه االتهــام إلــى ‪ ،........ /‬باملشــاركة يف‬\n                                     ‫ســرقة معــدات ثقيلــة عــن طريــق شــرائها‬\n                                                  ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n                  ‫‪ - 1‬ما جاء بأقواله املتضمنة اعترافه املرفقة لفة (‪0)12‬‬\n                                    ‫‪ -2‬ما جاء بأوراق املبايعة املرفقة لفة (‪0)8‬‬\n                                     ‫‪ -3‬ما جاء بصورة الشيك املرفق لفة (‪0)9‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا فعــل محــرم شــرع ًا ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه‬\n                                  ‫مبــا أســند إليــه ‪ ،‬واحلكــم بتعزيــره شــرعا‪0‬‬\n‫(علمــا بــأن املعــدات الثقيلــة قــد ســلمت ألصحابهــا) وبــاهلل التوفيــق هــذه‬\n‫دعــواي وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي‬\n‫العــام مــن قيامــي باملشــاركة يف ســرقة معــدات ثقيلــة عــن طريــق‬\n‫شــرائها فهــو غيــر صحيــح والصحيــح هــو أنــي اشــتريت هــذه املعــدات‬\n‫الثقيلــة املذكــورة يف دعــوى املدعــي العــام مــن املدعــو ‪ ........ /‬املســجون‬\n‫بســجون األحســاء عــن طريــق املدعــو ‪ ...... /‬ولــم أكــن أعلــم بــأن هــذه‬\n‫املعــدات مســروقة هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي العــام‬\n\n\n                                                                                        ‫‪144‬‬\n\f      ‫هــل لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد لــدي بينــة ســوى‬\n      ‫مــا جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق واالطــاع علــى‬\n      ‫أقــوال املدعــى عليــه حتقيق ـ ًا املدونــة علــى لفــة رقــم (‪ )12‬وعلــى أوراق‬\n      ‫املبايعــة املرفقــة علــى لفــة رقــم (‪ )8‬وعلــى صــورة الشــيك املرفــق علــى‬\n      ‫لفــة رقــم (‪ )9‬فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث إن‬\n      ‫املدعــى عليــه قــد أنكــر قيامــه بشــراء املعــدات الثقيلــة املذكــورة وهــو‬\n      ‫يعلــم بأنهــا مســروقة ولــم يعتــرف بذلــك حتقيقـ ًا و ألن قيــام املدعــى عليــه‬\n      ‫بشــراء املعــدات الثقيلــة املذكــورة ال يلــزم منــه علمــه بأنهــا مســروقة وملــا‬\n      ‫كان مــن املقــرر يف الشــريعة اإلســامية أن األصــل هــو بــراءة الذمــة‬\n      ‫قــال العــز بــن عبــد الســام رحمــه اهلل يف شــأن املدعــى عليــه ‪ (:‬فــإن‬\n      ‫األصــل بــراءة ذمتــه مــن احلقــوق وبــراءة جســده مــن القصــاص واحلــدود‬\n      ‫والتعزيــرات وبراءتــه مــن االنتســاب إلــى شــخص معــن و مــن األقاويــل‬\n      ‫كلهــا واألفعــال بأســرها ) قواعــد األحــكام ‪ 65/2‬وتأسيس ـ ًا علــى‬\n      ‫جميــع مــا ســبق فقــد قــررت مــا يأتــي أو ًال ‪ :‬لــم يثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه مبــا جــاء يف دعــوى املدعــي العــام ثاني ـ ًا ‪ :‬صرفــت النظــر عــن‬\n      ‫مطالبــة املدعــي العــام بتعزيــر املدعــى عليــه لعــدم ثبــوت موجــب ذلــك‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قنــع بــه كمــا قــرر املدعــي العــام االعتــراض بالئحــة وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                     ‫‪ 1434/02/09‬ه ـ الســاعة ‪09:00‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة ‪ .....‬علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة ‪ ......‬برقــم ‪ ........‬وتاريــخ‬\n\n\n‫‪145‬‬\n\f‫‪1434/4/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ..... /‬برقــم ‪ .....‬وتاريــخ ‪1434/2/13‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد ‪ ....... /‬يف قضيــة (ســرقة) علــى الصفــة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                      ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪146‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":141,"source_page_end":146,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93ec2e4de2301366d09668818ff9e032b0d1dfb22e5aa9bd7b918853af302d36","normalized_text_hash":"9ffb9d858e94f0d4130f8d49bd6c9c504faeb9984d9a10efca5f0b279a8801c2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p141-3436922"},{"id":"6c858c6b-fb5a-51e5-881d-1738b5faad00","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة دراجة نارية من داخل فناء املنزل -محضر ق صاص األثر -اتهام حدث -املطالبة بإقامة حد السرقة -شراء دراجة نارية مسروقة -صرف النظر عن دعوى املدعي العام -إخاء سبيل املدعى عليه .","document_number":"3452850","case_number":"3464883","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة ( )","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/02","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة دراجة نارية من داخل فناء املنزل -محضر ق صاص األثر -اتهام حدث -املطالبة بإقامة حد السرقة -شراء دراجة نارية مسروقة -صرف النظر عن دعوى املدعي العام -إخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك‪3452850 :‬تاريخه ‪1434/03/02 :‬هـ‬\n                           ‫رقم الدعوى ‪3464883 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34199859‬تاريخه ‪1434/4/28:‬ه‬\n\n\n\n      ‫ســرقة ‪ -‬انتهــاك حرمــة منــزل ‪ -‬ســرقة دراجــة ناريــة مــن داخــل فنــاء‬\n      ‫املنــزل ‪ -‬محضــر ُق ّصــاص األثــر ‪ -‬اتهــام حــدث ‪-‬املطالبــة بإقامــة حــد‬\n      ‫الســرقة ‪-‬شــراء دراجــة ناريــة مســروقة ‪ -‬صــرف النظــر عــن دعــوى‬\n                                  ‫املدعــي العــام ‪ -‬إخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n                                                    ‫‪-1‬قاعدة ‪ :‬األصل براءة الذمة ‪.‬‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه بســرقة دراجــة ناريــة مــن داخــل فنــاء أحــد‬\n      ‫املنــازل بعــد تســلقه للســور وفتــح بــاب الفنــاء وإخــراج الدراجــة‪ْ ،‬إذ تقــدم‬\n      ‫أحــد املواطنــن ببــاغ لــدى مركــز الشــرطة مفــاده تعــرض دراجتــه‬\n      ‫الناريــة للســرقه مــن داخــل غرفــه بفنــاء منزلــه ‪ ،‬جــرى االنتقــال ملســرح‬\n      ‫اجلرميــة ووصفــه ‪ ،‬وحضــر املجنــي عليــه مــرة أخــرى ملركــز الشــرطة‬\n      ‫وأفــاد أنــه شــاهد دراجتــه مــع أحــد األشــخاص ومت القبــض عليــه وتبــن‬\n      ‫أنــه َحـ َـدث‪ ،‬وأفــاد أنــه اشــترى الدراجــة مــن املدعــى عليــه‪ ،‬وبنــاء علــى‬\n      ‫ماذكــره طلــب املدعــي العــام إقامــة حــد الســرقة‪ ،‬وأنكــر املدعــى عليه‬\n      ‫مــا نســب إليــه ‪ ،‬وأحضــر املدعــي العــام بينــة غيــر موصلــة‪ ،‬لــذا صــدر‬\n      ‫احلكــم بصــرف النظــر عــن دعــوى املدعــي العــام وإخــاء ســبيل املدعــى‬\n                              ‫عليــه ‪ُ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n‫‪147‬‬\n\f‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة يف احملكمــة العامــة‬\n‫مبكــة املكرمــة (‪ )..................‬وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪3464883‬‬\n‫وتاريــخ ‪ 1434/02/09‬ه ـ املقيــدة باحملكمــة برقــم ‪34324073‬‬\n‫وتاريــخ ‪ 1434/02/09‬ه ـ ففــي يــوم الســبت املوافــق‪1434/02/23‬‬\n‫ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام بدائــرة االدعــاء العــام‬\n‫مبكــة املكرمــة وحضــر حلضــوره وبســؤال املدعــي العــام عــن دعــواه‬\n‫أبــرز الئحــة دعــوى مكونــة مــن ورقتــن هــذا نصهــا فبصفتــي مدعي ـ ًا‬\n‫عامـ ًا بدائــرة االدعــاء العــام مبكــة املكرمــة ادعــى علــى ‪ ، ...‬البالــغ مــن‬\n‫العمــر (‪ )23‬عامـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم()‬\n‫غيــر محصن‪،‬متعلم‪،‬مقيــم مبحافظــة ‪ ، ............‬اوقــف علــى ذمــة هــذه‬\n‫القضيــة منــذ ‪1433/10/28‬ه ـ بســجون مكــة املكرمــة مبوجــب امــر‬\n‫التوقيــف الصــادر مــن شــرطة العاصمــة املقدســةبرقم(‪ )1087‬وتاريــخ‬\n‫‪1433/11 /2‬ه ـ اســتنادا للقــرار الــوزاري رقم(‪)1900‬يف ‪1428/7/9‬هـ‬\n‫بتاريــخ ‪1432/8/15‬ه ـ تقــدم ملركــز شــرطة محافظــة اجلمــوم‪ /‬ببــاغ‬\n‫مفــاده تعــرض دراجتــه الناريــة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم (‪)......‬‬\n‫وهيــكل رقــم(‪ )....‬للســرقة مــن داخــل غرفــة بفنــاء منزلــه مبحافظــة‬\n‫‪ .......‬خلــف مطابــع الصاعــدي مــن قبــل أحــد األشــخاص قفــز مــن فــوق‬\n‫فنــاء املنــزل وفتــح البــاب املوصــد مــن الداخــل وأخــرج الدراجــة الناريــة‬\n                                                                           ‫منــه ‪.‬‬\n‫وقــد جــرى االنتقــال مــن قبــل مركــز الشــرطة إلــى مســرح اجلرميــة‬\n\n                                                                                       ‫‪148‬‬\n\f      ‫ومبعاينتــه اتضــح أنــه منــزل ســكني محــاط بســور بطــول (‪20×25‬م)‬\n      ‫تقريبـ ًا وبابــه اخلارجــي مــن احلديــد وبداخــل الفنــاء باجلهــة اليمنــى غرفــة‬\n      ‫حتــت اإلنشــاء ذكــر املدعــي أن الدراجــة الناريــة كانــت تقــف بهــا‬\n      ‫وشــوهدت آثــار إطــارات دراجــة ناريــة عنــد بــاب املدخــل الرئيســي وآثــار‬\n      ‫أقــدام ألحــد األشــخاص مــن أعلــى الســور لداخــل الفنــاء وشــوهدت‬\n      ‫آثــار إطــارات ســيارة بالقــرب مــن ســور املنــزل مــن اخلــارج واليوجــد آثــار‬\n      ‫كســر أو فــزر يف املنــزل أو البــاب اخلارجــي وجــرى اعــداد محضــر مــن‬\n      ‫قبــل قصــاص األثــر بأنــة شــوهد اثــار اطــارات لســيارة بالقــرب مــن ســور‬\n                                ‫املنــزل مــن اخلــارج يحتمــل أن تكــون مــن نــوع ‪...‬‬\n      ‫وبتاريــخ ‪1433/9/26‬ه ـ حضــر املجنــي عليــه املذكــور ملركز الشــرطة‬\n      ‫وأفــاد ب ــأنة أثنــاء مــروه بحــي ‪ ......‬مبحافظــة اجلمــوم شــاهد دراجتــه‬\n      ‫الناريــة مــع شــخص يدعــى‪ ........./‬فتــم القبــض عليــه وبســماع أقــوال‬\n      ‫احلــدث‪ ، .........../‬أفــاد بأنــه قــام بشــراء الدراجــة الناريــة املضبوطــة معــه‬\n      ‫مــن ‪ ........../‬مببلــغ وقــدره(‪ )700‬ســبعمائة ريــال مــن دون أوراق ثبوتيــه‪.‬‬\n      ‫باســتجواب‪ ،............/‬أفــاد بأنــه بــاع للحــدث‪ /‬الدراجــة الناريــة‬\n      ‫املضبوطــة معــه وأنــه أشــتري هــو الدراجــة الناريــة مــن املدعــى عليــه‬\n      ‫مببلــغ وقدره(‪)750‬ســبعمائة وخمســون ريــا ًال ويشــهد علــى ذلــك كل‬\n                                                 ‫مــن ‪................-2 ............-1 -:‬‬\n      ‫وبســماع شــهادة أفــاد بأنــه كان موجــود برفقــة عندمــا اشــترى الدراجــة‬\n                                          ‫الناريــة مببلغ(‪750‬ريــال) مــن املدعــى عليــه‬\n      ‫وبســماع شــهادة ‪ /‬أفــاد مبثــل مــا أفــاد بــه الشــاهد ومبواجهــة املدعــى‬\n      ‫عليــه ب‪ ........‬وبالشــاهدين أصــروا علــى اقوالهــم وأصــر الشــاهدان‬\n      ‫علــى أن أشــتري الدراجــة الناريــة املضبوطــة مــن املدعــى عليــه مببلــغ‬\n\n\n‫‪149‬‬\n\f                                        ‫وقــدره(‪ )750‬ســبعمائة وخمســون ريــا ًال ‪.‬‬\n‫وقــد انتهــى التحقيــق الــى توجيــه االتهــام للمدعــى عليــه بســرقة دراجــة‬\n‫ناريــة مــن داخــل غرفــة بفنــاء أحــد املنــازل بعــد تســلقه للســور اخلارجــي‬\n‫والقفــز للداخــل وفتــح بــاب الفنــاء املوصــد وإخــراج الدراجــة الناريــة منــه‬\n‫واملؤيــد مــن جلنــة ادارة الهيئــة بقرارهــا رقــم(‪/2530‬ر) وذلــك لألدلــة‬\n                                                                      ‫القرائــن التاليــة‪-:‬‬\n‫‪-1‬ماجــاء يف اقــوال بانــه اشــترى الدراجــة الناريــة املســروقة حســب‬\n‫اقــراره املــدون علــى ص(‪)12‬مــن دفتــر التحقيــق املرفــق لفــة(‪-2 )2‬مــا‬\n‫جــاء يف شــهادة الشــاهدين املدونــة علــى صفحــة رقــم(‪)13‬و(‪ )14‬مــن‬\n                                    ‫دفتــر التحقيــق املرفــق رقــم(‪ )2‬لفــه رقــم(‪.)2‬‬\n‫‪-3‬مــا جــاء مبحضــر االنتقــال واملعاينــة واملدونــة علــى صفحــة رقــم(‪)2‬‬\n                               ‫مــن دفتــر التحقيــق رقــم(‪ )1‬املرفقــه لفــه رقــم(‪. )1‬‬\n‫وبالبحــث عــن ســوابقة عثــر لــه علــى ســابقتني األولــى مضاربــة والثانيــة‬\n                         ‫شــرب املســكرات وســرقة الســيارات وصــدم واعتــداء‪.‬‬\n‫وحيــث إن ماقــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرعافعل محــرم ومعاقــب عليــه شــرع ًا وهــو أخــذ مــال محتــرم مــن‬\n‫حــرزه وقــد بلــغ النصــاب الشــبهة لــه فيــة لــذا أطلــب إثب ـ ـ ــات إدانتـ ـ ـ ــه‬\n‫مبــا أســند إليــه واحلكــم عليــه بحــد الســرقة الــوارد يف االيــة الكرميــة‬\n                                                          ‫رقم(‪)38‬مــن ســورة املائــدة‬\n‫علمــا بــأن احلــق اخلــاص العائــد للحــدث‪ ...... /‬مازال قائماوانتهى بالنســبة‬\n‫للمجنــي عليــه) وبعرضهــا علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n‫املدعــي العــام مــن ســرقتي للدراجــة الناريــة ال صحــة لــه وال علــم لــي بهــا‬\n‫هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام طلــب إمهالــه إلحضارها‬\n\n\n                                                                                              ‫‪150‬‬\n\f      ‫فأجيــب لطلبــه وعليــه رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي‬\n      ‫العــام كمــا حضــر املدعــى عليــه وبســؤال املدعــي العــام عمــا اســتمهل‬\n      ‫مــن أجلــه قــال إن بينتــي هــي شــهادة و علــى أن املدعــى عليــه قــد بــاع‬\n      ‫الدراجــة الناريــة املســروقة علــى وقــد تعــذر إحضــار الشــاهد األول‬\n      ‫لكونــه ســجني بقضيــة مخــدرات وأمــا الشــاهد الثانــي فقــد أحضرتــه‬\n      ‫وأطلــب ســماع مــا لديــه ثــم حضــر‪ .........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم‪ .........‬وعمــره عشــرون عامــا وال يعمــل وبســؤاله‬\n      ‫عمــا لديــه مــن شــهادة قــال أشــهد بــاهلل تعالــى إننــي حضــرت أنــا وابــن‬\n      ‫عمتــي وأخــوه لــدى املدعــى عليــه احلاضــر يف هــذه اجللســة يف شــهر رجــب‬\n      ‫مــن عــام ‪1432‬ه ـ وقــام املدعــى عليــه ببيعــه دراجــة ناريــة مــن نــوع ‪..........‬‬\n      ‫مببلــغ وقــدره ســبعمائة وخمســون ريــاال نقــدا واســتلم الدراجــة منــه وهــذا‬\n      ‫الدبــاب هــو نفــس الدبــاب الــذي مت القبــض علــى املدعــو وهــو بحوزتــه‬\n      ‫هكــذا شــهد فجــرى ســؤاله عــن تاريــخ البيــع بالتحديــد هــل هو يف شــهر‬\n      ‫رجــب أم يف جمــادى الثانيــة أم شــعبان فقــال إنــه يف رجــب أو جمــادى‬\n      ‫الثانيــة ال أذكــر بالتحديــد ولكنــه ليــس يف شــعبان قطعــا كمــا‬\n      ‫جــرى ســؤاله عــن ســنة إنتــاج الدراجــة بالتحديــد هــل هــي عــام ‪2006‬‬\n      ‫أم ‪ 2008‬أم ‪ 2010‬فقــال إنــه عــام ‪ 2006‬أو ‪ 2008‬لكونهــا تتشــابه يف‬\n      ‫الشــكل وأجــزم بكونــه ليــس مــن إنتــاج عــام ‪ 2010‬الختــاف الشــكل‬\n      ‫هكــذا أجــاب وبعــرض الشــاهد ومــا شــهد بــه علــى املدعــى عليــه قــال‬\n      ‫أمــا الشــاهد فــا أطعــن بــه وشــهادته غيــر صحيحــة هكــذا أجــاب‬\n      ‫وبالرجــوع إلــى أوراق املعاملــة وجــد باللفــة رقــم (‪ )7‬اســتمارة الدراجــة‬\n      ‫الناريــة وتتضمــن ملكيــة لدراجــة ناريــة رقــم اللوحــة ســنة الصنــع ‪2010‬‬\n      ‫ثــم جــرى ســؤال املدعــي العــام هــل لديــه زيــادة بينــة فقــال ليــس لــدي‬\n\n\n‫‪151‬‬\n\f‫ســوى مــا قدمــت فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار‬\n‫املدعــى عليــه مــا جــاء يف دعــوى املدعــي العــام ولــم يقــم املدعــي العــام‬\n‫بينــة موصلــة نظــرا لتناقــض مــا جــاء يف شــهادة الشــاهد احلاضــر مــع مــا‬\n‫جــاء يف الدعــوى حيــث إن الدعــوى تضمنــت أن الســرقة وقعــت بتاريــخ‬\n‫‪1432/8/15‬ه ـ وأن املســروق دراجــة ناريــة انتــاج عــام ‪ 2010‬وأن الثمــن‬\n‫كان ســبعمائة وخمســن ريــاال وجميــع ذلــك يتعــارض مــع مــا جــاء يف‬\n‫شــهادة الشــاهد بــل أكــد الشــاهد خالفــه ولكــون األصــل بــراءة الذمــة‬\n‫لــذا فإنــه لــم يثبــت لدينــا إدانــة املدعــى عليــه مبــا جــاء يف دعــوى املدعــي‬\n‫وصرفنــا النظــر عــن دعــوى املدعــي العــام وأخلينــا ســبيل املدعــى عليــه‬\n‫منهــا وبذلــك حكمنــا وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة بــه‬\n‫وقــرر املدعــي العــام عدمهــا وطلــب االســتئناف بالئحــة فأجيــب لطلبــه‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/03/02‬ه ـ‬\n         ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائرة اجلزائية اخلماســية األولى مبحكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‪34324073‬‬\n‫وتاريــخ ‪1434/4/10‬ه ـ املرفــق بهــا القــرار رقــم‪ 3452850‬وتاريــخ‬\n‫‪1434/3/2‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n‫العامــة مبكــة املكرمــة الشــيخ‪ ....../‬والشــيخ‪ ........../‬والشــيخ‪/‬‬\n‫املتضمــن دعــوى املدعــي العــام ضــد‪ ،....... /‬املتهم يف ســرقه ‪ ،‬احملكوم‬\n                                                             ‫فيــه مبــا دون باطنــه‬\n‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت‬\n\n\n                                                                                          ‫‪152‬‬\n\f      ‫املوافقــة علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪153‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":147,"source_page_end":153,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4caba5b6a52f23924c4a0b3f5811c3a1c4bbd6d69bb0a5d119aaaafa2533a11c","normalized_text_hash":"ad28568feb8b45bd12912311059bb6b145053c2a3dcf496379d24804289b4929","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p147-3452850"},{"id":"7016425c-62d3-5cc7-92c5-b26dc1f966b2","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -كسر قفل أحد املراكز التجارية -الشروع يف السرقة تستر املدعى عليه على آخر -عدم وجود سوابق إقرار املدعى عليه حتقيق ا تعزير للتهمة احلكم بالسجن واجللد أخذ تعهد .","document_number":"34165669","case_number":"3475727","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/18","year":"1434","subject":"سرقة -كسر قفل أحد املراكز التجارية -الشروع يف السرقة تستر املدعى عليه على آخر -عدم وجود سوابق إقرار املدعى عليه حتقيق ا تعزير للتهمة احلكم بالسجن واجللد أخذ تعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34165669 :‬تاريخه ‪1434/03/18 :‬هـ‬\n                     ‫رقم الدعوى ‪3475727 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 34201738‬تاريخه ‪1434/4/30:‬ه‬\n\n\n\n‫ســرقة ‪ -‬كســر قفــل أحــد املراكــز التجاريــة ‪ -‬الشــروع يف الســرقة ـ‬\n‫تســتر املدعــى عليــه علــى آخــر‪ -‬عــدم وجــود ســوابق ـ إقــرار املدعــى عليــه‬\n     ‫حتقيق ـ ًا ـ تعزيــر للتهمــة ـ احلكــم بالســجن واجللــد ـ أخــذ تعهــد ‪.‬‬\n\n\n\n\n              ‫ض َب ْع َد ِإ ْص َل ِح َها )‬      ‫ـ قول اهلل تعالى ( َو َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                           ‫ال ْر ِ‬\n                                                     ‫ـ قوله تعالى ( َو َال َت ْع َت ُدو ْا ِإ َّن ّ َ‬\n                        ‫الل َال ُي ِح ِّب ْالُ ْع َتدِ َ‬\n                     ‫ين )‬\n‫ـ قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                                               ‫ومالــه وعرضــه ) ‪.‬‬\n‫ـ قولــه صلــى اهلل عليــه وســلم ( فــإن دماؤكــم وأموالكــم وأعراضكــم‬\n‫حــرام عليكــم كحرمــة يومكــم هــذا يف شــهركم هــذا يف بلدكــم هذا)‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بكســر قفــل الســياج اخلارجــي‬\n‫ألحــد املراكــز التجاريــة والدخــول فيــه والشــروع يف الســرقة مــع أحــد‬\n‫األشــخاص وتســتره علــى زميلــه الهــارب ‪ ،‬حيــث تبلغــت اجلهــة األمنيــة‬\n‫مــن أحــد األشــخاص عــن تعــرض احملــل الــذي يعمــل بــه لكســر قفــل‬\n‫الســياج اخلارجــي للمحــل‪ ،‬ودخــول شــخصني محاولــن الســرقة يلبســان‬\n‫ـذاء رياضي ـ ًا أبيض ـاً‪ ،‬حســب مــا‬\n                                 ‫قناع ـ ًا يف الوجــه‪ ،‬وأحدهمــا يلبــس حـ ً‬\n\n                                                                                                        ‫‪154‬‬\n\f      ‫مت مشــاهدته مــن خــال كاميــرات املراقبــة‪ ،‬وبالبحــث والتحــري مت‬\n      ‫القبــض علــى املدعــى عليــه بالقــرب مــن املركز املذكــور وطلب املدعي‬\n      ‫العــام تعزيــره لذلــك‪ ،‬وأنكــر املدعــى عليــه ما جاء بدعــوى املدعي العام‬\n      ‫‪ ،‬لــذا طلبــت احملكمــة مــن املدعــي العالــم البينــة علــى مــا يدعيــه فقــرر‬\n      ‫أنــه ليــس لديــه ســوى مــا قدمــه ضمــن طيــات املعاملــة‪ ،‬وباالطــاع عليهــا‬\n      ‫وجــد مــن ضمنهــا تقريــر الدوريــات األمنيــة الســالف الذكــر‪ ،‬وعليــه‬\n      ‫حكمــت احملكمــة بعــدم إدانــة املدعــى عليــه عمــا جــاء بدعــوى املدعــي‬\n      ‫العــام وتعزيــره بالســجن واجللــد ألجــل التهمــة مــع أخــذ التعهــد‪ ،‬وقنــع‬\n      ‫املدعــى عليــه باحلكــم وقــرر املدعــي العــام املعارضة‪،‬وصــدق احلكــم‬\n                                                           ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫ـدي‬\n       ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n      ‫ـاء علــى املعاملــة‬\n                        ‫أنــا‪ ..........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n      ‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n      ‫برقــم ‪ 13957‬وتاريــخ ‪1433/12/21‬ه ـ واملقيــدة بهــذه احملكمــة‬\n      ‫برقــم وتاريــخ ‪1433/12/22‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس‬\n      ‫برقم‪33698479‬وتاريــخ ‪1433/12/22‬ه ـ فتحــت اجللســة األولــى يــوم‬\n      ‫األربعــاء ‪1434/02/13‬ه ـ الســاعة العاشــرة وفيهــا حضــر املدعــي العــام‬\n      ‫امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة رئيــس‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء ذي الرقــم ‪13415‬‬\n      ‫ا بصفتــي مدعي ـ ًا عام ـ ًا‬‫والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‪ ،........‬البالــغ‬\n\n‫‪155‬‬\n\f‫مــن العمــر (‪ )31‬عامـ ًا ‪ ،‬أفغانــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫(‪ ، )........‬أوقــف بتاريــخ ‪1433/12/1‬ه ـ وأحيــل لشــعبة ســجن محافظــة‬\n‫ا لديهــم برقــم (‪ )6‬مبوجــب املــادة (‪ )108‬مــن نظــام‬    ‫األحســاء وســجل نزيـ ً‬\n‫اإلجــراءات اجلزائيــة‪ .‬إنــه بتاريــخ ‪1433/12/1‬ه ـ ورد للشــرطة تقريــر‬\n‫الدوريــات األمنيــة املتضمــن بــاغ الوافــد‪ ......../‬مينــي اجلنســية رخصــة‬\n‫إقامــة (‪ )........‬عــن تعــرض مركــز للمــواد الغذائيــة الواقــع بحــي لكســر‬\n‫قفــل الســياج اخلارجــي والدخــول مــن قبــل شــخصني يلبســان قنــاع علــى‬\n‫الــرأس محاولــن الســرقة حســب مــا مت مشــاهدته مــن خــال كاميــرات‬\n‫املراقبــة الداخليــة ‪ ،‬وأضــاف املبلــغ أنــه عنــد انتهــاء فتــرة عملــه يف متــام‬\n‫الســاعة الواحــدة صباح ـ ًا ذهــب وزمالئــه إلــى مقــر ســكنهم للنــوم يف‬\n‫الــدور الثانــي مــن املركــز عندهــا ســمعوا صــوت جــرس اإلنــذار ونزلــوا‬\n‫مــن الســكن إلــى الــدور الســفلي ولــم يعثــروا علــى أحــد وعندمــا قامــوا‬\n‫بتفقــد شاشــة املراقبــة شــاهدوا شــخصني بداخــل احملــل يحتمــل إنهمــا‬\n‫يحــاوالن الســرقة حيــث إنهمــا متكنــوا مــن الدخــول بعــد قطــع احلديــد‬\n‫بــأداة حــادة كمــا أفــاد عــن عــدم تعــرض احملــل ألي ســرقة‪ .‬وباالنتقــال‬\n‫ومعاينــة احملــل اتضــح أنــه مركــز ‪ ........‬للمــواد الغذائيــة الواقــع بحــي‬\n‫‪ .....‬وشــوهد بــاب الســياج اخلارجــي للمحــل مفتــوح والقفــل التابــع لــه‬\n‫مكســور شــوهدت فتحــة بالــدور الثانــي صغيــرة بأعلــى الســقف طولهــا‬\n‫متــر ًا وعرضهــا ربــع متــر تقريبـ ًا التــي يحتمــل أن اجلنــاة دخــا إلــى احملــل‬\n‫مــن خاللهــا شــوهدت بعثــرة بداخــل احملــل وبالرجــوع إلــى كاميــرات‬\n‫املراقبــة الداخليــة شــوهد شــخصان أحدهمــا يلبــس حــذاء رياضــي‬\n‫لونــه أبيــض يلبســان قناعــن مت اتخــاذ الــازم‪ .‬وبالبحــث والتحــري عــن‬\n‫اجلنــاة مت القبــض علــى املدعــى عليــه بالقــرب مــن املركــز وباســتجواب‬\n\n\n                                                                                         ‫‪156‬‬\n\f      ‫املدعــى عليــه‪ :‬أقــر بتواجــده بالقــرب مــن احملــل وقــت احلادثــة‪ .‬وقــد‬\n      ‫أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بقيامــه رفــق شــخص هــارب‬\n      ‫بكســر قفــل الســياج اخلارجــي للمركــز التجــاري‪ ,‬مــن ثــم الدخــول فيــه‬\n      ‫والشــروع بالســرقة منــه وتســتره علــى زميلــه الهــارب ‪ ،‬وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة‪ -1 -:‬إقــراره املــدون علــى الصفحــة رقــم (‪ )5 ، 4‬مــن‬\n                                                    ‫ملــف التحقيــق املرفــق لفــة (‪.)2‬‬\n      ‫‪ -2‬تقريــر الدوريــة األمنيــة املتضمــن القبــض عليــه بالقــرب مــن املركــز‬\n                                                           ‫املذكــور املرفــق (‪.)7 ، 6‬‬\n      ‫‪ -3‬قدومــه حملافظــة األحســاء مــن منطقــة القصيــم وتواجــده مبوقــع‬\n      ‫القبــض يف وقــت متأخــر مــن الليــل الســيما أن مقــر إقامتــه وكفيلــه‬\n                           ‫مبنطقــة القصيــم قرينــة قاطعــة علــى صحــة االتهــام‪.‬‬\n      ‫‪ -4‬بــاغ املبلــغ املتضمــن تعــرض مركــز ‪ ........‬للمــواد الغذائيــة للدخــول‬\n                              ‫ومحاولــة الســرقة منــه مــن قبــل شــخصني مجهولــن‪.‬‬\n      ‫‪ -5‬إصــراره بعــدم اإلفصــاح عــن زميلــه الهــارب الــذي ذكــر أنــه قــدم‬\n      ‫إلــى األحســاء مــن أجلــه وعــدم تقــدمي مبــرر مقنــع عــن الشــخص الــذي‬\n      ‫معــه وتواجــده باملوقــع وقــت احلادثــة قرينــة تؤكــد صحــة االتهــام ممــا‬\n      ‫يؤكــد عــدم مصداقيتــه ومراوغتــه عــن اإلفصــاح باحلقيقــة ‪ -6‬انطبــاق‬\n      ‫مواصفــات أحــد الشــخصني اللذيــن شــوهدا يف التصويــر التلفزيونــي‬\n      ‫التابــع للمحــل علــى املدعــى عليــه قرينــة قاطعــة علــى صحــة االتهــام‪.‬‬\n      ‫وبالبحــث عمــا إذا كان لــه ســوابق‪ :‬لــم يعثــر لــه علــى ســوابق جنائيــة‬\n      ‫مســجلة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة وزاجــرة لغيــره لقــاء‬\n\n\n‫‪157‬‬\n\f‫فعلته‪(.‬علم ـ ًا أن احلــق اخلــاص يف كســر القفــل لــم ينتــه بعــد) هكــذا‬\n‫ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى‬\n‫عــرض دعــوى املدعــي العــام عليــه بواســطة املترجــم ‪.......‬هنــدي اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة الصــادرة من جوازات الهفوف برقم‪ ........‬مســلم‬\n‫ا ‪ :‬مــا ذكــره املدعــي العام‬      ‫ـروف لدينــا بالعدالــة فأجــاب قائـ ً‬\n                                                                      ‫الديانــة معـ ٌ‬\n‫مــن اتهامــي بالقيــام رفــق شــخص هــارب بكســر قفــل الســياج اخلارجــي‬\n‫ألحــد املراكــز التجاريــة ومــن ثــم الدخــول فيــه والشــروع بالســرقة منــه‬\n‫وتســتري علــى زميلــي الهــارب كل ذلــك غيــر صحيــح والصحيــح أننــي‬\n‫ـرت مــن القصيــم عنــد أحــد أصدقائــي ألجــل اصطحابه لــزواج أحد‬             ‫حضـ ُ‬\n‫أقربائــي بالدمــام وجلســت عنــده يوم ـ ًا وطلــب منــي ســيارتي املســتأجرة‬\n‫مت القبــض فيــه علـ َّـي وأخــذ‬     ‫إليصــال أهلــه إلــى الســوق يف اليــوم الــذي َّ‬\n‫الســيارة منــي ألجــل ذلــك وقــام بإنزالــي بإحــدى احلدائــق الســاعة احلاديــة‬\n‫عشــرة تقريبـ ًا وذهــب إليصــال أهلــه إلــى الســوق ثــم رجــع إلـ َّـي بعــد فتــرة‬\n‫وجلســنا ســويا ثــم اســتأذن إلرجــاع أهلــه مــن الســوق وتأخــر علـ َّـي إلــى‬\n‫الســاعة الواحــدة تقريب ـ ًا وقمــت باالتصــال بــه أكثــر مــن مــرة فلــم‬\n‫مت القبــض علــي‬       ‫يــر َّد علــي وحضــرت الشــرطة وأنــا جالــس باحلديقــة و َّ‬\n‫وال عالقــة لــي بهــذه الســرقة ال مــن قريــب وال مــن بعيــد هكــذا أجــاب‬\n‫ثــم جــرى ســؤال املدعــي العــام هــل لديــه بينــة علــى دعــواه فقــال ‪ :‬نعــم‬\n‫وهــي موجــودة يف أوراق املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب‬\n‫ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪ :‬إقــرار املدعــى‬\n‫عليــه حتقيق ـ ًا املــدون علــى رقــم(‪ )5-4‬مــن ملــف التحقيــق لفــة(‪ )2‬فلــم‬\n‫أجــد فيهــا مــا يديــن املدعــى عليــه مبــا نســب إليــه كمــا جــرى االطــاع‬\n‫مت القبــض علــى‬     ‫علــى تقريــر الدوريــات األمنيــة لفــة(‪ )7-6‬املتضمــن أنــه َّ‬\n\n\n                                                                                          ‫‪158‬‬\n\f      ‫املدعــى عليــه بالقــرب مركــز ‪ ........‬وأنــه قــام بتغييــر مالبســه عــدا‬\n      ‫اجلزمــة الرياضيــة واعتــرف بذلــك واتضــح أ َّنــه بحالــة ارتبــاك وبتفتيشــه‬\n      ‫لوحــظ كشــاف يف رجلــه ومبلــغ قــدره ‪2100‬ريــال وجــوال ‪ ...‬والشــخص‬\n      ‫الثانــي الذ بالفــرار والســيارة التــي اســتغلها اجلنــاة متوقفــة بالقــرب مــن‬\n      ‫ا ‪ :‬مــا ذكــر‬     ‫محــات ‪ ......‬ا‪.‬ه ـ وبعرضــه علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫فيــه غيــر صحيــح فلــم يكــن معــي كشــاف وإمنــا وجــده يف األرض بقرب‬\n      ‫املركــز التجــاري وأمــا اجلزمــة فقــد تتشــابه وأمــا املبلــغ فهــو لــي وقــد‬\n      ‫مت مصادرتــه دون وجــه حــق هكــذا قــرر كمــا جــرى االطــاع علــى‬                                   ‫َّ‬\n      ‫كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود ســوابق عليــه كمــا‬\n      ‫جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة أنــه أوقــف‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابة وبعد‬          ‫بتاريخ‪1433/12/01‬ه ـ فبنـ ً‬\n      ‫النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وبعــد دراســة أوراق‬\n      ‫أن املدعــى عليــه أنكــر دعــوى املدعــي العــام‬               ‫املعاملــة وتأملهــا ومبــا َّ‬\n      ‫باتهامــه بالقيــام رفــق شــخص هــارب بكســر قفــل الســياج اخلارجــي‬\n      ‫ألحــد املراكــز التجاريــة ومــن ثــم الدخــول فيــه والشــروع بالســرقة منــه‬\n      ‫وتســتره علــى زميلــه الهــارب وال بينــة للمدعــي العــام علــى ذلــك ســوى‬\n      ‫قرائـ ٍـن ال تقــوى علــى إثبــات إدانــة املدعــى عليــه بهــا ومبــا أ َّنــه يتهــم بذلــك‬\n      ‫ويــدل لــه مجمــوع القرائــن الســيما مــا ورد يف تقريــر الدوريــات األمنيــة‬\n      ‫{و َل ُت ْف ِسـ ُـدوا ِف‬\n                             ‫أن مــا يتهــم بــه مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬           ‫ومبــا َّ‬\n                     ‫{وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫الل ال ُي ِحـ ُّـب‬                           ‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬       ‫َْ‬\n                                                                                                       ‫ال ْر ِ‬\n      ‫ْال ُْع َتدِ يـ َـن } وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم‬\n            ‫كـ ْـم َو َأ ْم َوال ُ‬\n      ‫َكـ ْـم‬                    ‫((ف ـ ِإ َّن د َِم َاء ُ‬\n                                                      ‫وعرضــه)) وقــال ‪َ :‬‬        ‫ُ‬            ‫دم ـ ُه وما ُل ـ ُه‬\n                                                                                                                ‫ـرام ُ‬\n                                                                                                                    ‫حـ ٌ‬\n      ‫ك ْم‬ ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬     ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬\n                                                                         ‫كـ ْـم َ‬\n                                                                                ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬ ‫اض ُ‬‫َو َأ ْع َر َ‬\n\n‫‪159‬‬\n\f                                                                    ‫َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬\n‫كـ ْـم َهـ َـذا )) ممــا يســتوجب تعزيــر املدعــى عليــه لــذا كلــه‬\n‫وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أو ًال ‪ /‬لــم‬\n‫ـدي إدانــة املدعــى عليــه بالقيــام رفــق شــخص هــارب بكســر‬             ‫يثبــت لـ َّ‬\n‫قفــل الســياج اخلارجــي ألحــد املراكــز التجاريــة ومــن ثــم الدخــول فيــه‬\n‫والشــروع بالســرقة منــه وتســتره علــى زميلــه الهــارب وقــررت ر َّد دعــوى‬\n‫املدعــي العــام بإثبــات إدانتــه بذلــك ‪ .‬ثانيـ ًا ‪ /‬يعــزر ألجــل التهمــة بســجنه‬\n‫ثالثــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده ثمانــون جلــدة‬\n‫مفرقــة علــى دفعتــن كل دفعــة أربعــون جلــدة وبــن كل دفعــة وأخــرى‬\n‫مــدة ال تقــل عــن عشــرة أيــام ‪ .‬ثالث ـ ًا ‪ /‬يؤخــذ عليــه التعهــد بعــدم العــودة‬\n‫ملثــل مــا يتهــم بــه ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه‬\n‫بحقــه يف متييــز احلكــم بواســطة املترجــم قــرر القناعــة بــه وطلــب املدعــي‬\n‫العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n‫دون الئح ـ ٍة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى وأقفلــت‬\n‫اجللســة الســاعة التاســعة وصلــى اهلل وسـلَّم علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه أجمعــن‪ُ .‬حـ ِـر َر يف ‪1434/03/18‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/981800‬ج‪ 2‬وتاريــخ ‪1434/4/22‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫‪ 34380830‬وتاريــخ ‪1434/4/16‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ......../‬املســجل برقــم ‪34165669‬‬\n‫وتاريــخ ‪1434/3/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪......../‬‬\n‫(أفغانــي اجلنســية) يف قضيــة ســرقة مــال خــاص وقــد تضمــن القــرار‬\n\n\n                                                                                             ‫‪160‬‬\n\f      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطه وأوراق املعاملة قررنا املصادقة على احلكم‪ .‬واهلل املوفق وصلى‬\n      ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/27‬هــ‪.‬‬\n\n\n\n\n‫‪161‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":154,"source_page_end":161,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ca97b5cef19b7db59424c141fcdafeef979f18dfc2a2b36497be3de0800c88bb","normalized_text_hash":"673d79c442341928c1a5dcb3a779af1fe79c9c96f01d40fe390d731d9c9af22e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p154-34165669"}]$archive_payload$::jsonb) AS x LIMIT 25
